/* bible.js — ข้อความพระคัมภีร์ 2 ภาษา
 * TH: ฉบับสมาคมพระคริสตธรรมไทย 1971 (tbs_verses, dearteno/ThaiBibleXML)
 * EN: King James Version, public domain (thiagobodruk/bible)
 */
const BIBLE_VERSION = 'ฉบับสมาคมพระคริสตธรรมไทย 1971';
const BIBLE_VERSION_EN = 'King James Version (KJV)';
const BIBLE = {"กิจการฯ 2:42-47": [{"n": "42", "t": "เขาทั้งหลายได้ขะมักเขม้นฟังคำสอนของจำพวกอัครทูตและร่วมสามัคคีธรรม ทั้งขะมักเขม้นในการหักขนมปังและการอธิษฐาน"}, {"n": "43", "t": "เขามีความเกรงกลัวด้วยกันทุกคน และพวกอัครทูตทำการอัศจรรย์ และหมายสำคัญหลายประการ"}, {"n": "44", "t": "บรรดาผู้ที่เชื่อถือนั้นก็อยู่พร้อมกัน ณ ที่แห่งเดียว และทรัพย์สิ่งของของเขาเหล่านั้นเขาเอามารวมกันเป็นของกลาง"}, {"n": "45", "t": "เขาจึงได้ขายที่ดินและทรัพย์สิ่งของ มาแบ่งให้แก่คนทั้งปวงตามซึ่งทุกคนต้องการ"}, {"n": "46", "t": "เขาได้ร่วมใจกันไปในพระวิหาร และหักขนมปังตามบ้านของเขา ร่วมรับประทานอาหารด้วยความชื่นชมยินดีและใจกว้างขวาง ทุกวันเรื่อยไป"}, {"n": "47", "t": "ทั้งได้สรรเสริญพระเจ้าและคนทั้งปวงก็ชอบใจ ฝ่ายองค์พระผู้เป็นเจ้า ได้ทรงโปรดให้คนทั้งหลายซึ่งกำลังจะรอด มาเข้ากับพวกสาวกทุกวันๆ"}], "กิจการฯ 4:32-35": [{"n": "32", "t": "คนทั้งปวงที่เชื่อนั้นเป็นน้ำหนึ่งใจเดียวกัน และไม่มีใครอ้างว่าสิ่งของที่ตนมีอยู่เป็นของตน แต่ทั้งหมดเป็นของกลาง"}, {"n": "33", "t": "อัครทูตจึงประกอบด้วยฤทธิ์เดชใหญ่ยิ่ง เป็นพยานว่าพระเยซูเจ้าได้ทรงคืนพระชนม์แล้ว และพระคุณอันใหญ่ยิ่งได้อยู่กับเขาทุกคน"}, {"n": "34", "t": "เพราะว่าในพวกศิษย์ไม่มีผู้ใดขัดสน ผู้ใดมีไร่นาบ้านเรือนก็ขายเสีย"}, {"n": "35", "t": "และนำเงินค่าของที่ขายได้นั้นมาวางไว้ที่เท้าของอัครทูต อัครทูตจึงแจกจ่ายให้ทุกคนตามที่ต้องการ"}], "ฮีบรู 10:24-25": [{"n": "24", "t": "และขอให้เราพิจารณาดูว่าจะทำอย่างไร จึงจะปลุกใจซึ่งกันและกันให้มีความรักและทำความดี"}, {"n": "25", "t": "อย่าขาดการประชุมเหมือนอย่างบางคนที่ขาดอยู่นั้น แต่จงพูดหนุนใจกันให้มากยิ่งขึ้น เพราะท่านทั้งหลายก็รู้อยู่ว่าวันนั้นใกล้เข้ามาแล้ว"}], "โคโลสี 3:15-17": [{"n": "15", "t": "และจงให้สันติสุขของพระคริสต์ครองจิตใจของท่าน พระเจ้าทรงเรียกท่านไว้ให้เป็นกายเดียวด้วย เพื่อสันติสุขนั้น และท่านจงมีใจกตัญญู"}, {"n": "16", "t": "จงให้พระวาทะของพระคริสต์ดำรงอยู่ในตัวท่านอย่างบริบูรณ์ จงสั่งสอนและเตือนสติกันด้วยปัญญาทั้งสิ้น จงร้องเพลงสดุดีเพลงนมัสการ และเพลงสรรเสริญด้วยใจโมทนาขอบพระคุณพระเจ้า"}, {"n": "17", "t": "และเมื่อท่านจะกระทำสิ่งใดด้วยวาจาหรือด้วยกายก็ตาม จงกระทำทุกสิ่งในพระนามของพระเยซูเจ้า และขอบพระคุณพระบิดาเจ้า โดยพระองค์นั้น"}], "สดุดี 95:1-7": [{"n": "1", "t": "มาเถิด ให้เราทั้งหลายร้องเพลงถวายพระเจ้า ให้เรากระทำเสียงชื่นบานถวายพระศิลาแห่งความรอดของพวกเรา"}, {"n": "2", "t": "ให้เราทั้งหลายเข้ามาอยู่เฉพาะเบื้องพระพักตร์ด้วยโมทนา ให้เรากระทำเสียงชื่นบานถวายพระองค์ด้วยบทเพลงสรรเสริญ"}, {"n": "3", "t": "เพราะพระเยโฮวาห์ทรงเป็นพระเจ้าใหญ่ยิ่ง และทรงเป็นกษัตริย์ใหญ่ยิ่งเหนือพระทั้งหลาย"}, {"n": "4", "t": "ที่ลึกของแผ่นดินโลกอยู่ในพระหัตถ์ของพระองค์ที่สูงของภูเขาเป็นของพระองค์ด้วย"}, {"n": "5", "t": "ทะเลเป็นของพระองค์ เพราะพระองค์ทรงสร้างมันและพระหัตถ์ของพระองค์ทรงปั้นแผ่นดิน"}, {"n": "6", "t": "มาเถิดให้เรานมัสการและกราบลง ให้เราคุกเข่าลงต่อพระเจ้าผู้ทรงสร้างพวกเรา"}, {"n": "7", "t": "เพราะพระองค์ทรงเป็นพระเจ้าของเรา และเราเป็นประชากรแห่งทุ่งหญ้าของพระองค์ และเป็นแกะแห่งพระหัตถ์ของพระองค์ วันนี้ จะใคร่ให้ท่านทั้งหลายฟังพระสุรเสียงของพระองค์"}], "มัทธิว 6:5-15": [{"n": "5", "t": "\"เมื่อท่านทั้งหลายอธิษฐาน อย่าเป็นเหมือนคนหน้าซื่อใจคด เพราะเขาชอบยืนอธิษฐานในธรรมศาลาและตามถนน เพื่อจะให้คนทั้งปวงได้เห็น เราบอกความจริงแก่ท่านว่าเขาได้รับบำเหน็จของเขาแล้ว"}, {"n": "6", "t": "ฝ่ายท่านเมื่ออธิษฐานจงเข้าในห้องชั้นใน และเมื่อปิดประตูแล้ว จงอธิษฐานต่อพระบิดาของท่านผู้ทรงสถิตในที่ลี้ลับ และพระบิดาของท่านผู้ทรงเห็นในที่ลี้ลับจะทรงโปรดประทานบำเหน็จแก่ท่าน"}, {"n": "7", "t": "\"แต่เมื่อท่านอธิษฐานอย่าพูดพล่อยๆซ้ำซาก เหมือนคนต่างชาติกระทำเพราะเขาคิดว่าพูดมากหลายคำ พระจึงจะทรงโปรดฟัง"}, {"n": "8", "t": "อย่าทำเหมือนเขาเลย เพราะว่าสิ่งไรซึ่งท่านต้องการ พระบิดาของท่านทรงทราบก่อนที่ท่านทูลขอแล้ว"}, {"n": "9", "t": "\"ท่านทั้งหลาย จงอธิษฐานตามอย่างนี้ว่า ข้าแต่พระบิดาแห่งข้าพระองค์ทั้งหลาย ผู้ทรงสถิตในสวรรค์ ขอให้พระนามของพระองค์เป็นที่เคารพสักการะ"}, {"n": "10", "t": "ขอให้แผ่นดินของพระองค์มาตั้งอยู่ ขอให้เป็นไปตามพระทัยของพระองค์ ในสวรรค์เป็นอย่างไรก็ให้เป็นไปอย่างนั้นในแผ่นดินโลก"}, {"n": "11", "t": "ขอทรงโปรดประทานอาหารประจำวัน แก่ข้าพระองค์ทั้งหลายในกาลวันนี้"}, {"n": "12", "t": "และขอทรงโปรด ยกบาปผิดของข้าพระองค์ เหมือนข้าพระองค์ยกโทษผู้ที่ทำผิดต่อข้าพระองค์นั้น"}, {"n": "13", "t": "และขออย่านำข้าพระองค์เข้าไปในการทดลอง แต่ขอให้พ้นจากซึ่งชั่วร้าย {หรือ มารร้าย} [เหตุว่าราชอำนาจ และฤทธิ์เดช และพระสิริเป็นของพระองค์สืบๆไปเป็นนิตย์ อาเมน] {สำเนาต้นฉบับเก่าแก่หลายฉบับ ไม่มีข้อความนี้}"}, {"n": "14", "t": "เพราะว่าถ้าท่านยกความผิดของเพื่อนมนุษย์ พระบิดาของท่านผู้ทรงสถิตในสวรรค์จะทรงโปรดยกความผิดของท่านด้วย"}, {"n": "15", "t": "แต่ถ้าท่านไม่ยกความผิดของเพื่อนมนุษย์ พระบิดาของท่านจะไม่ทรงโปรดยกความผิดของท่านเหมือนกัน"}], "ลูกา 6:16-18": [{"n": "16", "t": "ยูดาสบุตรของยากอบ และยูดาส อิสคาริโอทที่เป็นผู้อายัดพระองค์ไว้นั้น"}, {"n": "17", "t": "แล้วพระองค์กับอัครทูตก็ลงมายืนณที่ราบแห่งหนึ่ง พร้อมกับหมู่สาวกของพระองค์ และประชาชนเป็นอันมาก ซึ่งมาจากทั่วแคว้นยูเดีย กรุงเยรูซาเล็มและจากตำบลชายทะเลในเขตเมืองไทระ และเมืองไซดอนเพื่อจะฟังพระองค์ และให้พระองค์ทรงรักษาโรคของเขา"}, {"n": "18", "t": "และบรรดาคนที่ต้องทนทุกข์เพราะผีโสโครก พระองค์ก็ทรงรักษาให้หายด้วย"}], "ฟีลิปปี 4:6-7; 1 เปโตร 5:7": [{"n": "ฟีลิปปี 4:6", "t": "อย่าทุกข์ร้อนในสิ่งใดๆเลย แต่จงทูลเรื่องความปรารถนาของท่านทุกอย่างต่อพระเจ้า ด้วยการอธิษฐาน การวิงวอน กับการขอบพระคุณ"}, {"n": "ฟีลิปปี 4:7", "t": "แล้วสันติสุขแห่งพระเจ้าซึ่งเกินความเข้าใจ จะคุ้มครองจิตใจและความคิดของท่านไว้ในพระเยซูคริสต์"}, {"n": "1 เปโตร 5:7", "t": "จงละความกระวนกระวายของท่านไว้กับพระองค์ เพราะว่าพระองค์ทรงห่วงใยท่านทั้งหลาย"}], "มัทธิว 4:1-11": [{"n": "1", "t": "ครั้งนั้น พระวิญญาณทรงนำพระเยซูเข้าไปในถิ่นทุรกันดาร เพื่อมารจะได้มาผจญ"}, {"n": "2", "t": "และพระองค์ทรงอดพระกระยาหารสี่สิบวันสี่สิบคืน ภายหลังพระองค์ก็ทรงอยากพระกระยาหาร"}, {"n": "3", "t": "ส่วนผู้ผจญมาหาพระองค์ทูลว่า \"ถ้าท่านเป็นพระบุตรของพระเจ้า จงสั่งก้อนหินเหล่านี้ให้กลายเป็นพระกระยาหาร\""}, {"n": "4", "t": "ฝ่ายพระองค์ตรัสตอบว่า \"มีพระคัมภีร์เขียนไว้ว่า \"มนุษย์จะบำรุงชีวิตด้วยอาหารสิ่งเดียวหามิได้ แต่บำรุงด้วยพระวจนะทุกคำ ซึ่งออกมาจากพระโอษฐ์ของพระเจ้า"}, {"n": "5", "t": "แล้วมารก็นำพระองค์ไปยังนครบริสุทธิ์ และให้พระองค์ประทับที่ยอดหลังคาพระวิหาร"}, {"n": "6", "t": "แล้วทูลพระองค์ว่า \"ถ้าท่านเป็นพระบุตรของพระเจ้า จงโจนลงไปเถิด เพราะพระคัมภีร์มีเขียนไว้ว่า พระเจ้าจะรับสั่งให้เหล่าทูตสวรรค์ของพระองค์รักษาท่าน และเหล่าทูตสวรรค์จะเอามือประคองชูท่านไว้ มิให้เท้าของท่านกระทบหิน"}, {"n": "7", "t": "พระเยซูจึงตรัสตอบว่า \"พระคัมภีร์มีเขียนไว้อีกว่า อย่าทดลองพระองค์ผู้เป็นพระเจ้าของท่าน"}, {"n": "8", "t": "อีกครั้งหนึ่งมารได้นำพระองค์ขึ้นไปบนภูเขาอันสูงยิ่งนัก และได้แสดงบรรดาราชอาณาจักรในโลก ทั้งความรุ่งเรืองของราชอาณาจักรเหล่านั้นให้พระองค์ทอดพระเนตร"}, {"n": "9", "t": "แล้วได้ทูลพระองค์ว่า \"ถ้าท่านจะกราบลงนมัสการเรา เราจะให้สิ่งทั้งปวงเหล่านี้แก่ท่าน\""}, {"n": "10", "t": "พระเยซูจึงตรัสตอบว่า \"อ้ายซาตาน จงไปเสียให้พ้น เพราะพระคัมภีร์มีเขียนไว้ว่า จงกราบนมัสการพระองค์ผู้เป็นพระเจ้าของท่าน และปรนนิบัติพระองค์แต่ผู้เดียว"}, {"n": "11", "t": "แล้วมารจึงละพระองค์ไป และมีเหล่าทูตสวรรค์มาปรนนิบัติพระองค์"}], "โยชูวา 24:15ข": [{"n": "15", "t": "และถ้าท่านไม่เต็มใจที่จะปรนนิบัติพระเจ้า ท่านทั้งหลายจงเลือกเสียในวันนี้ว่าท่านจะปรนนิบัติผู้ใด จะปรนนิบัติพระซึ่งบรรพบุรุษของท่านปรนนิบัติอยู่ในท้องถิ่นฟากตะวันออกของแม่น้ำยูเฟรติส หรือพระของคนอาโมไรต์ในแผ่นดินซึ่งท่านอาศัยอยู่ แต่ส่วนข้าพเจ้าและครอบครัวของข้าพเจ้า เราจะปรนนิบัติพระเจ้า\""}], "มัทธิว 6:19-21": [{"n": "19", "t": "\"อย่าส่ำสมทรัพย์สมบัติไว้สำหรับตัวในโลก ที่อาจเป็นสนิมและที่แมลงกินเสียได้ และที่ขโมยอาจขุดช่องลักเอาไปได้"}, {"n": "20", "t": "แต่จงส่ำสมทรัพย์สมบัติไว้ในสวรรค์ ที่ไม่มีแมลงจะกินและไม่มีสนิมจะกัด และที่ไม่มีขโมยขุดช่องลักเอาไปได้"}, {"n": "21", "t": "เพราะว่าทรัพย์สมบัติของท่านอยู่ที่ไหน ใจของท่านก็อยู่ที่นั่นด้วย"}], "มาระโก 12:41-44": [{"n": "41", "t": "พระเยซูได้เสด็จประทับตรงหน้าตู้เก็บเงินถวาย ทรงสังเกตประชาชนเอาเงินมาใส่ไว้ในตู้นั้น และคนมั่งมีหลายคนเอาเงินมากมาใส่ในที่นั้น"}, {"n": "42", "t": "มีหญิงม่ายคนหนึ่งเป็นคนจนเอาเหรียญทองแดงสองอัน มีค่าประมาณสลึงหนึ่งมาใส่ไว้"}, {"n": "43", "t": "พระองค์จึงทรงเรียกเหล่าสาวกมาตรัสแก่เขาว่า \"เราบอกความจริงแก่ท่านทั้งหลายว่า หญิงม่ายจนคนนี้ได้ใส่ไว้ในตู้เก็บเงินถวายมากกว่าคนทั้งปวงที่ใส่ไว้นั้น"}, {"n": "44", "t": "เพราะว่าคนทั้งปวงนั้นได้เอาเงินเหลือใช้ของเขามาใส่ไว้ แต่ผู้หญิงนี้ขัดสนที่สุด ยังได้เอาเงินที่มีอยู่สำหรับเลี้ยงชีวิตของตนมาใส่จนหมด\""}], "กิจการฯ 9:36-39": [{"n": "36", "t": "ในเมืองยัฟฟามีหญิงคนหนึ่งเป็นศิษย์ ชื่อทาบิธา ตามภาษากรีกว่าโดรคัสแปลว่าเนื้อสมัน หญิงคนนี้เคยกระทำการอันเป็นคุณประโยชน์และให้ทานมามากแล้ว"}, {"n": "37", "t": "ระหว่างนั้นหญิงคนนี้ก็ป่วยลงจนถึงแก่ความตาย เขาจึงอาบน้ำศพวางไว้ในห้องชั้นบน"}, {"n": "38", "t": "เมืองลิดดาอยู่ใกล้กับเมืองยัฟฟา พวกสาวกได้ยินว่าเปโตรอยู่ที่นั่น จึงใช้คนสองคนไปเชิญชวนว่า \"เชิญมาหาโดยเร็ว\""}, {"n": "39", "t": "ฝ่ายเปโตรจึงลุกขึ้นไปกับเขา เมื่อถึงแล้วเขาพาท่านขึ้นไปในห้องชั้นบน และบรรดาหญิงม่ายได้ยืนอยู่กับท่านพากันร้องไห้ และชี้ให้ท่านดูเสื้อผ้าต่างๆซึ่งโดรคัสทำเมื่อยังมีชีวิตอยู่"}], "1 โครินธ์ 16:1-3": [{"n": "1", "t": "เรื่องการเรี่ยไรเพื่อช่วยธรรมิกชนนั้น ข้าพเจ้าได้สั่งคริสตจักรที่แคว้นกาลาเทียว่าอย่างไร ก็ขอให้ท่านจงกระทำเหมือนกันด้วย"}, {"n": "2", "t": "ทุกวันต้นสัปดาห์ ให้พวกท่านทุกคนเก็บเงินผลประโยชน์ที่ได้รับไว้บ้าง เพื่อจะไม่ต้องเก็บเรี่ยไรเมื่อข้าพเจ้ามา"}, {"n": "3", "t": "เมื่อข้าพเจ้ามาถึงแล้ว พวกท่านเห็นชอบจะเลือกผู้ใด ข้าพเจ้าจะใช้ผู้นั้นถือหนังสือและเงินถวายของท่านไปยังกรุงเยรูซาเล็ม"}], "1 เปโตร 4:10-11": [{"n": "10", "t": "ตามซึ่งทุกคนได้รับของประทานที่ทรงประทานให้แล้ว ก็ให้ใช้ของประทานนั้นเพื่อประโยชน์แก่กันและกัน เป็นผู้รับมอบฉันทะที่ดี ที่แจกและสำแดงพระคุณนานาประการของพระเจ้า"}, {"n": "11", "t": "ถ้าผู้หนึ่งผู้ใดจะพูด ก็ให้กล่าวเหมือนหนึ่งกล่าวพระภาษิตของพระเจ้า ถ้าคนใดกระทำบริการ ก็จงให้บริการตามกำลังซึ่งพระเจ้าทรงโปรดประทาน เพื่อว่าพระเจ้าจะทรงได้เกียรติในการทั้งปวง โดยทางพระเยซูคริสต์ พระสิริและไอศวรรยานุภาพจงมีแด่พระองค์ตลอดไปเป็นนิตย์ อาเมน"}], "ยอห์น 15:4-10": [{"n": "4", "t": "จงเข้าสนิทอยู่ในเรา และเราเข้าสนิทอยู่ในท่าน แขนงจะออกผลเองไม่ได้ นอกจากจะติดอยู่กับเถาฉันใด ท่านทั้งหลายก็จะเกิดผลไม่ได้ นอกจากจะเข้าสนิทอยู่ในเราฉันนั้น"}, {"n": "5", "t": "เราเป็นเถาองุ่น ท่านทั้งหลายเป็นแขนง ผู้ที่เข้าสนิทอยู่ในเราและเราเข้าสนิทอยู่ในเขา ผู้นั้นก็จะเกิดผลมาก เพราะถ้าแยกจากเราแล้วท่านจะทำสิ่งใดไม่ได้เลย"}, {"n": "6", "t": "ถ้าผู้ใดมิได้เข้าสนิทอยู่ในเรา ผู้นั้นก็ต้องถูกตัดทิ้งเสียเหมือนแขนง แล้วก็เหี่ยวแห้งไป และถูกเก็บเอาไปเผาไฟ"}, {"n": "7", "t": "ถ้าท่านทั้งหลายเข้าสนิทอยู่ในเรา และถ้อยคำของเราฝังอยู่ในท่านแล้ว ท่านจะขอสิ่งใด ซึ่งท่านปรารถนาก็จะได้สิ่งนั้น"}, {"n": "8", "t": "พระบิดาของเราทรงได้รับเกียรติเพราะเหตุนี้คือเมื่อท่านทั้งหลายเกิดผลมาก ท่านก็เป็นสาวกของเรา"}, {"n": "9", "t": "พระบิดาทรงรักเราฉันใด เราก็รักท่านทั้งหลายฉันนั้น จงยึดมั่นอยู่ในความรักของเรา"}, {"n": "10", "t": "ถ้าท่านทั้งหลายประพฤติตามบัญญัติของเรา ท่านก็จะยึดมั่นอยู่ในความรักของเรา เหมือนดังที่เราประพฤติตามพระบัญญัติของพระบิดา และยึดมั่นอยู่ในความรักของพระองค์"}], "กาลาเทีย 5:16-26": [{"n": "16", "t": "แต่ข้าพเจ้าขอบอกว่า จงดำเนินชีวิตตามพระวิญญาณ อย่าสนองความต้องการของเนื้อหนัง"}, {"n": "17", "t": "เพราะว่าความต้องการของเนื้อหนังต่อสู้พระวิญญาณ และพระวิญญาณก็ต่อสู้เนื้อหนัง เพราะทั้งสองฝ่ายเป็นศัตรูกัน ดังนั้นสิ่งที่ท่านทั้งหลายปรารถนาทำจึงกระทำไม่ได้"}, {"n": "18", "t": "แต่ถ้าพระวิญญาณทรงนำท่าน ท่านก็จะไม่อยู่ใต้ธรรมบัญญัติ"}, {"n": "19", "t": "การงานของเนื้อหนังนั้นเห็นได้ชัด คือการล่วงประเวณี การโสโครก การลามก"}, {"n": "20", "t": "การนับถือรูปเคารพ การถือวิทยาคม การเป็นศัตรูกัน การวิวาทกัน การริษยากัน การโกรธกัน การใฝ่สูง การทุ่มเถียงกัน การแตกก๊กกัน"}, {"n": "21", "t": "การอิจฉากัน การเมาเหล้า การเล่นเป็นพาลเกเร และการอื่นๆในทำนองนี้อีกเหมือนที่ข้าพเจ้าได้เตือนท่านมาก่อน บัดนี้ข้าพเจ้าขอเตือนท่านเหมือนกับที่เคยเตือนมาแล้วว่า คนที่ประพฤติเช่นนั้นจะไม่มีส่วนในแผ่นดินของพระเจ้า"}, {"n": "22", "t": "ฝ่ายผลของพระวิญญาณนั้น คือความรัก ความปลาบปลื้มใจ สันติสุข ความอดกลั้นใจ ความปรานี ความดี ความสัตย์ซื่อ"}, {"n": "23", "t": "ความสุภาพอ่อนน้อม การรู้จักบังคับตน เรื่องอย่างนี้ไม่มีธรรมบัญญัติห้ามไว้เลย"}, {"n": "24", "t": "ผู้ที่อยู่ฝ่ายพระเยซูคริสต์ได้เอาเนื้อหนังกับความอยาก และตัณหาของเนื้อหนังตรึงไว้ที่กางเขนแล้ว"}, {"n": "25", "t": "ถ้าเรามีชีวิตอยู่โดยพระวิญญาณก็จงดำเนินชีวิตตามพระวิญญาณด้วย"}, {"n": "26", "t": "เราอย่าถือตัว อย่ายั่วโทสะกัน และอย่าอิจฉาริษยากันเลย"}], "1 เปโตร 1:3-9": [{"n": "3", "t": "สาธุการแด่พระเจ้าพระบิดาแห่งพระเยซูคริสตเจ้าของเรา ผู้ได้ทรงพระมหากรุณาแก่เรา ทรงโปรดให้เราบังเกิดใหม่ เข้าสู่ความหวังใจอันมีชีวิตอยู่ โดยการคืนพระชนม์ของพระเยซูคริสต์"}, {"n": "4", "t": "และเพื่อให้ได้รับมรดก ซึ่งไม่รู้เปื่อยเน่า ปราศจากมลทิน และไม่ร่วงโรยซึ่งได้เตรียมไว้ในสวรรค์เพื่อท่านทั้งหลาย"}, {"n": "5", "t": "ซึ่งเป็นผู้ที่ฤทธิ์เดชของพระเจ้าได้ทรงคุ้มครองไว้ด้วยความเชื่อให้ถึงความรอด ซึ่งพร้อมแล้วที่จะปรากฏในวาระสุดท้าย"}, {"n": "6", "t": "ในความรอดนั้นท่านทั้งหลายชื่นชมยินดี ถึงแม้ว่าเดี๋ยวนี้ จำเป็นที่ท่านจะต้องทนทุกข์ทรมานชั่วขณะหนึ่งในการถูกทดลองต่างๆ"}, {"n": "7", "t": "เพื่อการลองดูความเชื่อของท่าน อันประเสริฐยิ่งกว่าทองคำ ซึ่งแม้เสียไปได้ก็ยังถูกลองด้วยไฟ จะได้เป็นเหตุให้เกิดความสรรเสริญเกิดศักดิ์ศรีและเกียรติ ในเวลาที่พระเยซูคริสต์จะเสด็จมาปรากฏ"}, {"n": "8", "t": "พระองค์ผู้ที่ท่านทั้งหลายยังไม่ได้เห็น แต่ท่านยังรักพระองค์อยู่แม้ว่าขณะนี้ท่านไม่เห็นพระองค์ แต่ท่านยังเชื่อและชื่นชม ด้วยความปีติยินดีเป็นล้นพ้นเหลือที่จะกล่าวได้"}, {"n": "9", "t": "แล้ววิญญาณจิตของท่านทั้งหลายจึงได้รับความรอดเป็นผลแห่งความเชื่อ"}], "โรม 8:1-11": [{"n": "1", "t": "เหตุฉะนั้นการลงโทษจึงไม่มีแก่คนทั้งหลายที่อยู่ในพระเยซูคริสต์"}, {"n": "2", "t": "เพราะว่ากฎของพระวิญญาณแห่งชีวิต ในพระเยซูคริสต์ ได้ทำให้ข้าพเจ้าพ้นจากกฎแห่งบาปและความตาย"}, {"n": "3", "t": "เพราะว่าสิ่งซึ่งธรรมบัญญัติทำไม่ได้ เพราะเนื้อหนังทำให้อ่อนกำลังไปนั้น พระเจ้าได้ทรงกระทำแล้ว โดยพระองค์ทรงใช้พระบุตรของพระองค์มา ในสภาพเสมือนเนื้อหนังที่บาป และเพื่อไถ่บาป {หรือ เป็นเครื่องบูชาไถ่คนจากบาป} พระบุตรในเนื้อหนังจึงได้ทรงปรับโทษบาป"}, {"n": "4", "t": "เพื่อสิ่งที่ธรรมบัญญัติสั่งไว้จะได้สำเร็จในตัวเราทั้งหลาย ผู้ไม่ดำเนินตามฝ่ายเนื้อหนัง แต่ตามฝ่ายพระวิญญาณ"}, {"n": "5", "t": "เพราะว่าคนทั้งหลายที่อยู่ฝ่ายเนื้อหนัง ก็ปักใจในสิ่งซึ่งเป็นของของเนื้อหนัง แต่คนทั้งหลายที่อยู่ฝ่ายพระวิญญาณ ก็สนใจในสิ่งซึ่งเป็นของพระวิญญาณ"}, {"n": "6", "t": "ด้วยว่าซึ่งปักใจอยู่กับเนื้อหนัง ก็คือความตาย และซึ่งปักใจอยู่กับพระวิญญาณก็คือชีวิตและสันติสุข"}, {"n": "7", "t": "เหตุว่าใจซึ่งปักอยู่กับเนื้อหนังนั้นก็เป็นศัตรูต่อพระเจ้า หาได้อยู่ใต้บังคับธรรมบัญญัติของพระเจ้าไม่ และที่จริงจะอยู่ใต้บังคับธรรมบัญญัตินั้นไม่ได้"}, {"n": "8", "t": "และคนทั้งหลายที่อยู่ใต้เนื้อหนัง จะเป็นที่ชอบพระทัยพระเจ้าก็หามิได้"}, {"n": "9", "t": "ถ้าพระวิญญาณของพระเจ้าทรงสถิตอยู่ในท่านทั้งหลายจริงๆแล้วท่านก็มิได้อยู่ใต้เนื้อหนัง แต่อยู่ใต้พระวิญญาณ ผู้ใดไม่มีพระวิญญาณของพระคริสต์ ผู้นั้นก็ไม่เป็นของพระองค์"}, {"n": "10", "t": "และถ้าพระคริสต์อยู่ในท่านทั้งหลายแล้ว ถึงแม้ว่าร่างกายของท่านจะตายไปเพราะบาป แต่วิญญาณจิตของท่านก็จะดำรงอยู่เพราะความชอบธรรม"}, {"n": "11", "t": "ถ้าพระวิญญาณของพระองค์ ผู้ทรงชุบให้พระเยซูเป็นขึ้นมาจากความตาย ทรงสถิตอยู่ในท่านทั้งหลาย พระองค์ผู้ทรงชุบให้พระเยซูคริสต์เป็นขึ้นมาจากความตายแล้วนั้น จะทรงกระทำให้กายซึ่งต้องตายของท่าน เป็นขึ้นมาใหม่ โดยเดชแห่งพระวิญญาณของพระองค์ซึ่งทรงสถิตอยู่ในท่านทั้งหลาย"}], "โรม 8:31-37": [{"n": "31", "t": "ถ้าเช่นนั้นเราจะว่าอย่างไร ถ้าพระเจ้าทรงอยู่ฝ่ายเรา ใครจะขัดขวางเรา"}, {"n": "32", "t": "พระองค์ผู้มิได้ทรงหวงพระบุตรองค์เดียวของพระองค์ แต่ได้ทรงโปรดประทานพระบุตรนั้นเพื่อประโยชน์แก่เรา ถ้าเช่นนั้นพระองค์จะไม่ทรงโปรดประทานสิ่งสารพัดให้เราทั้งหลาย ด้วยกันกับพระบุตรนั้นหรือ"}, {"n": "33", "t": "ใครจะฟ้องคนเหล่านั้นที่พระเจ้าได้ทรงเลือกไว้ พระเจ้าทรงโปรดให้พ้นโทษแล้ว"}, {"n": "34", "t": "ใครเล่าจะเป็นผู้ปรับโทษอีก พระเยซูคริสต์น่ะหรือ ผู้ทรงสิ้นพระชนม์แล้ว และยิ่งกว่านั้นอีกได้ทรงถูกชุบให้เป็นขึ้นมาจากความตาย ทรงสถิตณเบื้องขวาพระหัตถ์ของพระเจ้า และทรงอธิษฐานขอเพื่อเราทั้งหลายด้วย"}, {"n": "35", "t": "แล้วใครจะให้เราทั้งหลายขาดจากความรักของพระคริสต์ได้เล่า จะเป็นความทุกข์ หรือความยากลำบาก หรือการเคี่ยวเข็ญ หรือการกันดารอาหาร หรือการเปลือยกาย หรือการถูกโพยภัย หรือการถูกคมดาบหรือ"}, {"n": "36", "t": "ตามที่เขียนไว้ในพระคัมภีร์ว่า เพราะเห็นแก่พระองค์ ข้าพระองค์จึงถูกประหารวันยังค่ำ และนับว่าเป็นแกะสำหรับจะเอาไปฆ่า"}, {"n": "37", "t": "แต่ว่าในเหตุการณ์ทั้งปวงเหล่านี้ เรามีชัยเหลือล้นโดยพระองค์ผู้ได้ทรงรักเราทั้งหลาย"}], "ยอห์น 14:15-21": [{"n": "15", "t": "\"ถ้าท่านทั้งหลายรักเรา ท่านก็จะประพฤติตามบัญญัติของเรา"}, {"n": "16", "t": "เราจะทูลขอพระบิดา และพระองค์จะประทานผู้ช่วยอีกผู้หนึ่งให้แก่ท่าน เพื่อจะได้อยู่กับท่านตลอดไป"}, {"n": "17", "t": "คือพระวิญญาณแห่งความจริง ซึ่งโลกรับไว้ไม่ได้ เพราะแลไม่เห็นและไม่รู้จักพระองค์ ท่านทั้งหลายรู้จักพระองค์ เพราะพระองค์ทรงสถิตอยู่กับท่าน และจะประทับอยู่ในท่าน"}, {"n": "18", "t": "\"เราจะไม่ละทิ้งท่านทั้งหลายไว้ให้เปล่าเปลี่ยว เราจะมาหาท่าน"}, {"n": "19", "t": "อีกหน่อยหนึ่งโลกก็จะไม่เห็นเรา แต่ท่านทั้งหลายจะเห็นเรา เพราะเราดำรงอยู่ ท่านทั้งหลายก็จะดำรงอยู่ด้วย"}, {"n": "20", "t": "ในวันนั้นท่านทั้งหลายจะรู้ว่าเราอยู่ในพระบิดา และท่านอยู่ในเราและเราอยู่ในท่าน"}, {"n": "21", "t": "ผู้ใดที่มีบัญญัติของเรา และประพฤติตามบัญญัตินั้น ผู้นั้นแหละเป็นผู้ที่รักเรา และผู้ที่รักเรานั้นพระบิดาของเราจะทรงรักเขา และเราจะรักเขา และจะสำแดงตัวให้ปรากฏแก่เขา\""}], "มัทธิว 25:35-36": [{"n": "35", "t": "เพราะว่าเมื่อเราหิว ท่านทั้งหลายก็ได้จัดหาให้เรากิน เรากระหายน้ำ ท่านก็ให้เราดื่ม เราเป็นแขกแปลกหน้า ท่านก็ได้ต้อนรับเราไว้"}, {"n": "36", "t": "เราเปลือยกายท่านก็ได้ให้เสื้อผ้าเรานุ่งห่ม เมื่อเราเจ็บป่วยท่านก็ได้มาเยี่ยมเอาใจใส่เรา เมื่อเราต้องจำอยู่ในพันธนาคาร ท่านก็ได้มาเยี่ยมเรา\""}], "1 โครินธ์ 13:4-7": [{"n": "4", "t": "ความรักนั้นก็อดทนนานและกระทำคุณให้ ความรักไม่อิจฉา ไม่อวดตัว"}, {"n": "5", "t": "ไม่หยิ่งผยอง ไม่หยาบคาย ไม่คิดเห็นแก่ตนเองฝ่ายเดียว ไม่ฉุนเฉียว ไม่ช่างจดจำความผิด"}, {"n": "6", "t": "ไม่ชื่นชมยินดีเมื่อมีการประพฤติผิด แต่ชื่นชมยินดีเมื่อประพฤติชอบ"}, {"n": "7", "t": "ความรักทนได้ทุกอย่างแม้ความผิดของคนอื่น และเชื่อในส่วนดีของเขาอยู่เสมอ และมีความหวังอยู่เสมอ และทนต่อทุกอย่าง"}], "ลูกา 10:25-37": [{"n": "25", "t": "ดูเถิด มีบาเรียนคนหนึ่งยืนขึ้นทดลองพระองค์ ทูลถามว่า \"อาจารย์เจ้าข้า ข้าพเจ้าจะต้องทำอะไรเพื่อจะได้ชีวิตนิรันดร์\""}, {"n": "26", "t": "พระองค์ตรัสตอบว่า \"ในธรรมบัญญัติมีคำเขียนว่าอย่างไร ท่านได้อ่านเข้าใจอย่างไร\""}, {"n": "27", "t": "เขาทูลตอบว่า \"จงรักพระองค์ผู้เป็นพระเจ้าของเจ้าด้วยสุดจิตสุดใจของเจ้า ด้วยสุดกำลังและสิ้นสุดความคิดของเจ้า และจงรักเพื่อนบ้านเหมือนรักตนเอง"}, {"n": "28", "t": "พระองค์จึงตรัสแก่เขาว่า \"ท่านตอบถูกแล้ว จงกระทำอย่างนั้นแล้วจะได้ชีวิต \""}, {"n": "29", "t": "แต่คนนั้นปรารถนาจะแก้ตัว จึงทูลพระเยซูว่า \"ใครเป็นเพื่อนบ้านของข้าพเจ้า\""}, {"n": "30", "t": "พระเยซูตรัสตอบว่า \"มีชายคนหนึ่งลงไปจากกรุงเยรูซาเล็มจะไปยังเมืองเยรีโค และเขาถูกพวกโจรปล้น โจรนั้นได้แย่งชิงเสื้อผ้าของเขาและทุบตี แล้วก็ละทิ้งเขาไว้เกือบจะตายแล้ว"}, {"n": "31", "t": "เผอิญปุโรหิตคนหนึ่งเดินลงไปทางนั้น เมื่อเห็นคนนั้นก็เดินเลยไปเสียอีกฟากหนึ่ง"}, {"n": "32", "t": "คนหนึ่งในพวกเลวีก็ทำเหมือนกัน เมื่อมาถึงที่นั่นและเห็นแล้วก็เลยไปเสียอีกฟากหนึ่ง"}, {"n": "33", "t": "แต่ชาวสะมาเรียคนหนึ่ง เมื่อเดินทางมาถึงคนนั้น ครั้นเห็นแล้วก็มีใจเมตตา"}, {"n": "34", "t": "เข้าไปหาเขาเอาผ้าพันบาดแผลให้พลางเอาน้ำมันกับเหล้าองุ่นเทใส่บาดแผลนั้น แล้วให้เขาขึ้นขี่สัตว์ของตนเอง พามาถึงโรงแรมแห่งหนึ่ง และรักษาพยาบาลเขาไว้"}, {"n": "35", "t": "วันรุ่งขึ้นเมื่อจะไป เขาก็เอาเงินสองเดนาริอันมอบให้เจ้าของโรงแรม บอกว่า \"จงรักษาเขาไว้เถิด และเงินที่จะเสียเกินนี้ เมื่อกลับมาฉันจะใช้ให้\""}, {"n": "36", "t": "ในสามคนนั้น ท่านคิดเห็นว่าคนไหนปรากฏว่าเป็นเพื่อนบ้านของคนที่ถูกปล้น\""}, {"n": "37", "t": "เขาทูลตอบว่า \"คือคนนั้นแหละที่ได้สำแดงความเมตตาแก่เขา\" พระเยซูจึงตรัสกับเขาว่า \"ท่านจงไปทำเหมือนอย่างนั้นเถิด\""}], "มัทธิว 5:43-48": [{"n": "43", "t": "\"ท่านทั้งหลายได้ยินคำซึ่งกล่าวไว้ว่า จงรักคนสนิท และเกลียดชังศัตรู"}, {"n": "44", "t": "ฝ่ายเราบอกท่านว่า จงรักศัตรูของท่าน และจงอธิษฐานเพื่อผู้ที่ข่มเหงท่าน"}, {"n": "45", "t": "ทำดังนี้แล้วท่านทั้งหลายจะเป็นบุตรของพระบิดาของท่านผู้ทรงสถิตในสวรรค์ เพราะว่าพระองค์ทรงให้ดวงอาทิตย์ของพระองค์ ขึ้นส่องสว่างแก่คนดีและคนชั่วเสมอกัน และให้ฝนตก แก่คนชอบธรรมและคนอธรรม"}, {"n": "46", "t": "แม้ว่าท่านรักผู้ที่รักท่าน จะได้บำเหน็จอะไร ถึงพวกเก็บภาษีก็ยังกระทำอย่างนั้นมิใช่หรือ"}, {"n": "47", "t": "ถ้าท่านทักทายแต่พี่น้องของตนฝ่ายเดียว ท่านได้กระทำอะไรเป็นพิเศษยิ่งกว่าคนทั้งปวงเล่า ถึงคนต่างชาติก็กระทำอย่างนั้นมิใช่หรือ"}, {"n": "48", "t": "เหตุฉะนี้ท่านทั้งหลายจงเป็นคนดีรอบคอบ เหมือนอย่างพระบิดาของท่าน ผู้ทรงสถิตในสวรรค์เป็นผู้ดีรอบคอบ"}], "มัทธิว 26:26-30": [{"n": "26", "t": "ระหว่างอาหารมื้อนั้น พระเยซูทรงหยิบขนมปังมา และเมื่อถวายสาธุการแล้ว ทรงหักส่งให้แก่เหล่าสาวกตรัสว่า \"จงรับกินเถิด นี่เป็นกายของเรา\""}, {"n": "27", "t": "แล้วพระองค์จึงทรงหยิบถ้วยโมทนาพระคุณและส่งให้เขา ตรัสว่า \"จงรับไปดื่มทุกคนเถิด"}, {"n": "28", "t": "ด้วยว่านี่เป็นโลหิตของเรา อันเป็นโลหิตแห่งพันธสัญญา ซึ่งต้องหลั่งออกเพื่อยกบาปโทษคนเป็นอันมาก"}, {"n": "29", "t": "เราบอกท่านทั้งหลายว่า เราจะไม่ดื่มน้ำผลแห่งเถาองุ่นต่อไปอีกจนวันนั้นมาถึง คือวันที่เราจะดื่มกันใหม่กับพวกท่านในแผ่นดินแห่งพระบิดาของเรา\""}, {"n": "30", "t": "เมื่อร้องเพลงสรรเสริญแล้ว เขาก็พากันออกไปยังภูเขามะกอกเทศ"}], "1 โครินธ์ 11:23-29": [{"n": "23", "t": "เพราะว่าเรื่องซึ่งข้าพเจ้าได้มอบไว้กับท่านแล้วนั้น ข้าพเจ้าได้รับจากองค์พระผู้เป็นเจ้า คือในคืนที่เขาอายัดพระเยซูเจ้านั้น พระองค์ทรงหยิบขนมปัง"}, {"n": "24", "t": "ครั้นขอบพระคุณแล้วจึงทรงหัก แล้วตรัสว่า \"นี่เป็นกายของเรา ซึ่งให้แก่ท่านทั้งหลาย จงกระทำอย่างนี้ให้เป็นที่ระลึกถึงเรา\""}, {"n": "25", "t": "เมื่อรับประทานแล้ว พระองค์จึงทรงหยิบถ้วยด้วยอาการอย่างเดียวกัน ตรัสว่า \"ถ้วยนี้คือพันธสัญญาใหม่ โดยโลหิตของเรา เมื่อท่านดื่มจากถ้วยนี้เวลาใด จงดื่มเป็นที่ระลึกถึงเรา\""}, {"n": "26", "t": "เพราะว่าเมื่อท่านทั้งหลายกินขนมปังนี้และดื่มจากถ้วยนี้เวลาใด ท่านก็ประกาศการวายพระชนม์ขององค์พระผู้เป็นเจ้า จนกว่าพระองค์จะเสด็จมา"}, {"n": "27", "t": "เหตุฉะนั้นถ้าผู้ใดกินขนมปัง หรือดื่มจากถ้วยขององค์พระผู้เป็นเจ้าอย่างไม่สมควร ผู้นั้นก็ทำผิดต่อพระกายและพระโลหิตขององค์พระผู้เป็นเจ้า"}, {"n": "28", "t": "ขอให้ทุกคนพิจารณาตนเอง แล้วจึงกินขนมปังและดื่มจากถ้วยนี้"}, {"n": "29", "t": "เพราะว่าคนที่กินและดื่มโดยมิได้เล็งเห็นพระกายขององค์พระผู้เป็นเจ้า ก็กินและดื่มเป็นเหตุให้ตนเองถูกพิพากษาโทษ"}], "มัทธิว 28:19-20": [{"n": "19", "t": "เหตุฉะนั้นเจ้าทั้งหลายจงออกไปสั่งสอนชนทุกชาติ ให้เป็นสาวกของเรา ให้รับบัพติศมาในพระนามแห่งพระบิดา พระบุตรและพระวิญญาณบริสุทธิ์"}, {"n": "20", "t": "สอนเขาให้ถือรักษาสิ่งสารพัดซึ่งเราได้สั่งพวกเจ้าไว้ นี่แหละเราจะอยู่กับเจ้าทั้งหลายเสมอไป จนกว่าจะสิ้นยุค\""}], "กิจการฯ 8:26-39": [{"n": "26", "t": "แต่ทูตองค์หนึ่งขององค์พระผู้เป็นเจ้าได้สั่งฟีลิปว่า \"จงลุกขึ้น ไปยังทิศใต้ตามทางที่ลงไปจากกรุงเยรูซาเล็มถึงเมืองกาซา\" (ซึ่งเป็นทางเปล่าเปลี่ยว)"}, {"n": "27", "t": "ฝ่ายฟีลิปก็ลุกขึ้นไป และดูเถิดมีชาวเอธิโอเปียคนหนึ่งเป็นขันที เป็นข้าราชการของพระนางคานดาสีพระราชินีของชาวเอธิโอเปีย และเป็นนายคลังทรัพย์ทั้งหมดของพระราชินีนั้น ได้มานมัสการในกรุงเยรูซาเล็ม"}, {"n": "28", "t": "ขณะนั่งรถกลับไป ท่านอ่านหนังสืออิสยาห์ผู้เผยพระวจนะอยู่"}, {"n": "29", "t": "ฝ่ายพระวิญญาณตรัสสั่งฟีลิปว่า \"จงเข้าไปให้ชิดรถนั้นเถิด\""}, {"n": "30", "t": "ฟีลิปจึงวิ่งเข้าไปใกล้ และได้ยินท่านอ่านหนังสืออิสยาห์ผู้เผยพระวจนะ จึงถามว่า \"ซึ่งท่านอ่านนั้นท่านเข้าใจหรือ\""}, {"n": "31", "t": "ขันทีจึงตอบว่า \"ถ้าไม่มีใครอธิบายให้ ที่ไหนจะเข้าใจได้\" ท่านจึงเชิญฟีลิปขึ้นนั่งรถกับท่าน"}, {"n": "32", "t": "พระคัมภีร์ตอนที่ท่านอ่านอยู่นั้น คือข้อเหล่านี้ เขาได้นำท่านเหมือนอย่างนำแกะไปฆ่า และเหมือนลูกแกะนิ่งอยู่ต่อหน้าผู้ตัดขนของมันฉันใด ท่านไม่ปริปากของท่านเลยฉันนั้น"}, {"n": "33", "t": "ในคราวที่ท่านถูกเหยียดลงนั้น ท่านไม่ได้รับความยุติธรรมเสียเลย ใครจะเล่าถึงเชื้อสายของท่านได้ เพราะว่าชีวิตของท่านต้องถูกตัดเสียจากแผ่นดินโลกแล้ว"}, {"n": "34", "t": "ขันทีจึงถามฟีลิปว่า \"ผู้เผยพระวจนะได้กล่าวอย่างนั้นเล็งถึงผู้ใด เล็งถึงตัวท่านเอง หรือเล็งถึงผู้อื่น บอกข้าพเจ้าเถิด\""}, {"n": "35", "t": "ฝ่ายฟีลิปจึงเริ่มเล่าจับต้นกล่าวตามพระคัมภีร์ข้อนั้น ชี้แจงถึงข่าวประเสริฐเรื่องพระเยซู"}, {"n": "36", "t": "ครั้นกำลังเดินทางไปก็มาถึงที่มีน้ำแห่งหนึ่ง ขันทีจึงบอกว่า \"นี่แน่ะ มีน้ำ มีอะไรขัดข้องไม่ให้ข้าพเจ้ารับบัพติศมา\""}, {"n": "37", "t": "และฟีลิปจึงตอบว่า \"ถ้าท่านเต็มใจเชื่อท่านก็รับได้\" และขันทีจึงตอบว่า \"ข้าพเจ้าเชื่อว่า พระเยซูคริสต์ทรงเป็นพระบุตรของพระเจ้า\""}, {"n": "38", "t": "แล้วท่านจึงสั่งให้หยุดรถ และคนทั้งสองลงไปในน้ำทั้งฟีลิปกับขันที ฟีลิปก็ให้ท่านรับบัพติศมา"}, {"n": "39", "t": "เมื่อท่านทั้งสองขึ้นจากน้ำแล้ว พระวิญญาณบริสุทธิ์ขององค์พระผู้เป็นเจ้าทรงรับฟีลิปไปเสีย และขันทีนั้นไม่ได้เห็นท่านอีก จึงเดินทางต่อไปด้วยความพอใจ"}], "โรม 6:1-9": [{"n": "1", "t": "ถ้าเช่นนั้นแล้วเราจะว่าอย่างไร ควรเราจะอยู่ในบาปต่อไป เพื่อให้พระคุณมีมากยิ่งขึ้นหรือ"}, {"n": "2", "t": "อย่าให้เป็นอย่างนั้นเลย พวกเราที่ตายต่อบาปแล้วจะมีชีวิตในบาปต่อไปอย่างไรได้"}, {"n": "3", "t": "ท่านไม่รู้หรือว่า เราทั้งหลายที่ได้รับบัพติศมาเข้าในพระเยซูคริสต์ ก็ได้รับบัพติศมานั้นเข้าในความตายของพระองค์"}, {"n": "4", "t": "เหตุฉะนั้น เราจึงถูกฝังไว้กับพระองค์แล้ว โดยการรับบัพติศมาเข้าส่วนในการตายนั้น เพื่อว่าเมื่อพระคริสต์ได้ทรงถูกชุบให้เป็นขึ้นมาจากความตายโดยเดชพระสิริของพระบิดาแล้ว เราก็จะได้ดำเนินตามชีวิตใหม่ด้วยเหมือนกัน"}, {"n": "5", "t": "เพราะว่าถ้าเราเข้าสนิทกับพระองค์แล้วในการตายอย่างพระองค์ เราก็จะเข้าสนิทกับพระองค์ ในการเป็นขึ้นมาอย่างพระองค์ได้ทรงเป็นขึ้นมาจากความตายด้วย"}, {"n": "6", "t": "เราทั้งหลายรู้แล้วว่า ตัวเก่าของเรานั้นได้ถูกตรึงไว้กับพระองค์แล้ว เพื่อตัวที่บาปนั้นจะถูกทำลายให้สิ้นไป และเราจะไม่เป็นทาสของบาปอีกต่อไป"}, {"n": "7", "t": "เพราะว่าผู้ที่ตายแล้วก็พ้นจากบาป"}, {"n": "8", "t": "แต่ถ้าเราตายแล้วกับพระคริสต์ เราเชื่อว่าเราจะมีชีวิตอยู่กับพระองค์ด้วย"}, {"n": "9", "t": "เราทั้งหลายรู้อยู่ว่า พระคริสต์ที่ทรงถูกชุบให้เป็นขึ้นมาจากตายนั้นแล้วจะหาตายอีกไม่ ความตายหาครอบงำพระองค์ต่อไปไม่"}], "2 ทิโมธี 3:10-17": [{"n": "10", "t": "บัดนี้ ท่านก็ประจักษ์ชัดแล้วซึ่งคำสอน พฤติการ ความมุ่งหมายในชีวิต ความเชื่อ ความอดทน ความรัก ความหนักแน่นมั่นคง"}, {"n": "11", "t": "การถูกข่มเหง การทนทุกข์ยากลำบากของข้าพเจ้าและสิ่งที่ได้เกิดขึ้นกับข้าพเจ้าณเมืองอันทิโอก เมืองอิโคนียูม และเมืองลิสตรา การกดขี่ข่มเหงที่ข้าพเจ้าได้ทนเอา ถึงกระนั้นก็ดี องค์พระผู้เป็นเจ้าได้ทรงโปรดให้ข้าพเจ้ารอดพ้นจากสิ่งเหล่านั้นทั้งหมด"}, {"n": "12", "t": "แท้จริงบรรดาคนที่ปรารถนาจะดำเนินชีวิตตามทางของพระเจ้า ในพระเยซูคริสต์จะถูกกดขี่ข่มเหง"}, {"n": "13", "t": "ขณะเมื่อคนชั่วและคนเจ้าเล่ห์จะเลวลง ทั้งล่อลวงคนอื่นและถูกคนอื่นล่อลวงด้วย"}, {"n": "14", "t": "แต่ฝ่ายท่านจงดำเนินต่อไปในสิ่งที่ท่านเรียนรู้แล้วและได้เชื่ออย่างมั่นคง ท่านก็รู้ว่าท่านได้เรียนมาจากผู้ใด"}, {"n": "15", "t": "และตั้งแต่เด็กมาแล้ว ที่ท่านได้รู้พระคัมภีร์อันศักดิ์สิทธิ์ ซึ่งสามารถสอนท่านให้ถึงความรอดได้โดยความเชื่อในพระเยซูคริสต์"}, {"n": "16", "t": "พระคัมภีร์ ทุกตอนได้รับการดลใจจากพระเจ้า และ {หรือ ทุกตอนที่ได้รับการดลใจจากพระเจ้า ก็} เป็นประโยชน์ในการสอนการตักเตือนว่ากล่าวการปรับปรุงแก้ไขคนให้ดี และการอบรมในทางธรรม"}, {"n": "17", "t": "เพื่อคนของพระเจ้าจะพรักพร้อมที่จะกระทำการดีทุกอย่าง"}], "โยชูวา 1:7-9": [{"n": "7", "t": "เพียงแต่จงเข้มแข็งและกล้าหาญยิ่งเถิด ระวังที่จะกระทำตามธรรมบัญญัติทั้งหมด ซึ่งโมเสสผู้รับใช้ของเราได้บัญชาเจ้าไว้นั้น อย่าหลีกเลี่ยงจากธรรมบัญญัตินั้นไปทางขวามือหรือทางซ้าย เพื่อว่าเจ้าจะไปในถิ่นฐานใดเจ้าจะได้รับความสำเร็จอย่างดี"}, {"n": "8", "t": "อย่าให้หนังสือธรรมบัญญัตินี้ห่างเหินไปจากปากของเจ้า แต่เจ้าจงตรึกตรองตามนั้นทั้งกลางวันและกลางคืน เพื่อเจ้าจะได้ระวังที่จะกระทำตามข้อความที่เขียนไว้นั้นทุกประการ แล้วเจ้าจะมีความจำเริญ และเจ้าจะสำเร็จผลเป็นอย่างดี"}, {"n": "9", "t": "เราสั่งเจ้าไว้แล้วมิใช่หรือว่าจงเข้มแข็งและกล้าหาญเถิด อย่าตกใจหรือคร้ามกลัวเลย เพราะว่าเจ้าไปในถิ่นฐานใด พระเยโฮวาห์พระเจ้าของเจ้าทรงสถิตกับเจ้า\""}], "ยากอบ 1:22-25": [{"n": "22", "t": "แต่ท่านทั้งหลายจงเป็นคนที่ประพฤติตามพระวจนะนั้น ไม่ใช่เป็นแต่เพียงผู้ฟังเท่านั้น ซึ่งเป็นการลวงตนเอง"}, {"n": "23", "t": "เพราะว่าถ้าผู้ใดฟังพระวจนะ และไม่ได้ประพฤติตาม ผู้นั้นก็เป็นเหมือนคนที่ดูหน้าของตัวในกระจกเงา"}, {"n": "24", "t": "เพราะว่าเมื่อดูตัวเองแล้วก็ไป และก็ลืมในทันทีนั้นว่าตัวเองเป็นอย่างไร"}, {"n": "25", "t": "แต่ผู้ที่พิจารณาดูในวิสุทธิบัญญัติ ซึ่งเป็นพระบัญญัติแห่งเสรีภาพ และตั้งอยู่ในพระบัญญัตินั้น มิได้เป็นผู้ฟังแล้วก็หลงลืม แต่เป็นผู้ที่ประพฤติปฏิบัติตาม ผู้นั้นก็จะได้รับความสุขเพราะการประพฤติปฏิบัติของตน"}], "ฉธบ. 31:12-13": [{"n": "12", "t": "จงเรียกประชาชนให้มาประชุมกันทั้งชาย หญิง และเด็ก ทั้งคนต่างด้าวในเมืองของท่านเพื่อให้เขาได้ยินและเรียนรู้ที่จะยำเกรงพระเยโฮวาห์พระเจ้าของท่าน และให้ระวังที่จะกระทำตามถ้อยคำทั้งสิ้นของธรรมบัญญัตินี้"}, {"n": "13", "t": "และเพื่อบุตรหลานทั้งหลายของเขาผู้ยังไม่ทราบจะได้ยิน และเรียนรู้ที่จะยำเกรงพระเยโฮวาห์พระเจ้าของท่าน ตราบเท่าเวลาซึ่งท่านอยู่ในแผ่นดิน ซึ่งท่านกำลังจะยกข้ามแม่น้ำจอร์แดนไปยึดครองนั้น\""}], "กิจการฯ 17:11": [{"n": "11", "t": "ยิวชาวเมืองนั้นมีจิตใจสูงกว่าชาวเมืองเธสะโลนิกา ด้วยเขามีใจเลื่อมใสรับพระวจนะของพระเจ้า และค้นดูพระคัมภีร์ทุกวัน หวังจะรู้ว่าข้อความเหล่านั้นจะจริงดังกล่าวหรือไม่"}], "มัทธิว 28:18-20": [{"n": "18", "t": "พระเยซูจึงเสด็จเข้ามาใกล้แล้วตรัสกับเขาว่า \"ฤทธานุภาพทั้งสิ้นในสวรรค์ก็ดี ในแผ่นดินโลกก็ดีทรงมอบไว้แก่เราแล้ว"}, {"n": "19", "t": "เหตุฉะนั้นเจ้าทั้งหลายจงออกไปสั่งสอนชนทุกชาติ ให้เป็นสาวกของเรา ให้รับบัพติศมาในพระนามแห่งพระบิดา พระบุตรและพระวิญญาณบริสุทธิ์"}, {"n": "20", "t": "สอนเขาให้ถือรักษาสิ่งสารพัดซึ่งเราได้สั่งพวกเจ้าไว้ นี่แหละเราจะอยู่กับเจ้าทั้งหลายเสมอไป จนกว่าจะสิ้นยุค\""}], "2 ทิโมธี 2:1-3": [{"n": "1", "t": "เหตุฉะนั้นบุตรของข้าพเจ้าเอ๋ย จงเข้มแข็งขึ้นในพระคุณซึ่งมีอยู่ในพระเยซูคริสต์"}, {"n": "2", "t": "จงมอบคำสอนเหล่านั้น ซึ่งท่านได้ยินจากข้าพเจ้าต่อหน้าพยานหลายคน ไว้กับคนที่ซื่อสัตย์ที่สามารถสอนคนอื่นได้ด้วย"}, {"n": "3", "t": "จงทนการยากลำบากด้วยกันกับทหารที่ดีของพระเยซูคริสต์"}], "กิจการฯ 18:24-27": [{"n": "24", "t": "มียิวคนหนึ่งชื่ออปอลโล เกิดในเมืองอเล็กซานเดรีย เป็นคนมีโวหารดี และชำนาญมากในทางพระคัมภีร์ ท่านมายังเมืองเอเฟซัส"}, {"n": "25", "t": "อปอลโลคนนี้ได้รับการอบรมในทางขององค์พระผู้เป็นเจ้า และมีใจร้อนรนกล่าวสั่งสอนอย่างถูกต้องถึงเรื่องพระเยซู ถึงแม้ท่านรู้แต่เพียงบัพติศมาของยอห์นเท่านั้น"}, {"n": "26", "t": "ท่านได้เข้าไปในธรรมศาลาสั่งสอนโดยใจกล้า แต่เมื่อปริสสิลลากับอาควิลลาได้ฟังท่านแล้ว เขาจึงรับท่านมาสั่งสอนให้รู้ทางของพระเจ้าให้ถูกต้องยิ่งขึ้น"}, {"n": "27", "t": "ครั้นอปอลโลจะใคร่ข้ามไปยังแคว้นอาคายา พวกพี่น้องก็หนุนใจเขา และได้เขียนจดหมายฝากไปถึงสาวกที่นั่นให้เขารับรองท่านไว้ ครั้นท่านไปถึงแล้ว ท่านได้ช่วยเหลือคนทั้งหลายที่ได้เชื่อโดยพระคุณของพระเจ้าอย่างมากมาย"}], "ลูกา 10:1-9": [{"n": "1", "t": "ภายหลังเหตุการณ์เหล่านั้นพระเยซูทรงตั้งสาวกอื่นอีกเจ็ดสิบคนไว้ และใช้เขาออกไปทีละสองคนๆให้ล่วงหน้าพระองค์ไปก่อน ให้เข้าไปทุกเมืองและทุกตำบลที่พระองค์จะเสด็จไปนั้น"}, {"n": "2", "t": "พระองค์ตรัสกับเขาว่า \"ข้าวที่ต้องเกี่ยวนั้นมีมากแต่คนงานยังน้อยอยู่ เหตุฉะนั้นพวกท่านจงอ้อนวอนพระองค์ผู้ทรงเป็นเจ้าของนา ให้ส่งคนงานมาเก็บเกี่ยวพืชผลของพระองค์"}, {"n": "3", "t": "ไปเถอะ ดูเถิด เราใช้ท่านทั้งหลายไปดุจลูกแกะอยู่ท่ามกลางฝูงสุนัขป่า"}, {"n": "4", "t": "อย่าเอาไถ้เงิน หรือย่าม หรือรองเท้าไป และอย่าคำนับผู้ใดตามทาง"}, {"n": "5", "t": "ถ้าจะเข้าไปในเรือนใดๆจงพูดก่อนว่า \"ให้ความสุขมีแก่เรือนนี้เถิด\""}, {"n": "6", "t": "ถ้าลูกแห่งสันติสุขอยู่ที่นั่น สันติสุขของท่านจะอยู่กับเขา ถ้าหาไม่ สันติสุขของท่านจะกลับอยู่กับท่านอีก"}, {"n": "7", "t": "จงอาศัยอยู่ในเรือนนั้น กินและดื่มของซึ่งเขาจะให้นั้น ด้วยว่าผู้ทำงานสมควรจะได้รับค่าจ้างของตน อย่าเที่ยวจากเรือนนี้ไปเรือนโน้น"}, {"n": "8", "t": "ถ้าท่านจะเข้าไปในเมืองใดๆและเขารับรองท่านไว้จงกินของที่เขาตั้งให้"}, {"n": "9", "t": "และจงรักษาคนป่วยในเมืองนั้นให้หาย และแจ้งแก่เขาว่า \"แผ่นดินของพระเจ้ามาใกล้ท่านทั้งหลายแล้ว\""}], "เอเฟซัส 4:17-28": [{"n": "17", "t": "เหตุฉะนั้นข้าพเจ้าจึงขอยืนยันและเป็นพยานในองค์พระผู้เป็นเจ้าว่า ตั้งแต่บัดนี้เป็นต้นไปท่านอย่าประพฤติอย่างคนต่างชาติที่เขาประพฤติกันนั้น คือมีใจจดจ่ออยู่กับสิ่งที่ไร้สาระ"}, {"n": "18", "t": "โดยที่ความคิดของเขามืดมนไป และเขาอยู่ห่างจากชีวิตซึ่งมาจากพระเจ้า เพราะเหตุความไม่รู้เท่าถึงการซึ่งอยู่ในตัวเขา อันเนื่องจากใจที่แข็งกระด้างของเขา"}, {"n": "19", "t": "เขามีใจปราศจากโอตตัปปะปล่อยตัวทำการลามกและละโมบในกาม ทำการโสโครกทุกอย่าง"}, {"n": "20", "t": "แต่ว่าท่านไม่ได้เรียนรู้จักพระคริสต์อย่างนั้น"}, {"n": "21", "t": "ถ้าแม้ท่านได้ฟังเรื่องพระองค์ และได้เรียนรู้เรื่องพระองค์ตามสัจธรรม ซึ่งมีอยู่ในพระเยซูแล้ว"}, {"n": "22", "t": "ท่านจงทิ้งตัวเก่าของท่าน ซึ่งคู่กับวิถีชีวิตเดิมนั้นเสีย อันจะเสื่อมเสียไปสู่ความตายตามตัณหาอันเป็นที่หลอกลวง"}, {"n": "23", "t": "และจงให้วิญญาณจิตของท่านเปลี่ยนใหม่"}, {"n": "24", "t": "และให้ท่านสวมสภาพใหม่ ซึ่งทรงสร้างขึ้นใหม่ตามแบบอย่างของพระเจ้า ในความชอบธรรมและความบริสุทธิ์ที่แท้จริง"}, {"n": "25", "t": "เหตุฉะนั้นท่านจงเลิกพูดมุสาเสีย และ จงพูดความจริงต่อกัน เพราะว่าเราต่างก็เป็นอวัยวะของกันและกัน"}, {"n": "26", "t": "จะโกรธก็โกรธได้ แต่อย่าทำบาป อย่าให้ถึงตะวันตกท่านยังโกรธอยู่"}, {"n": "27", "t": "และอย่าให้โอกาสแก่มาร"}, {"n": "28", "t": "คนที่เคยขโมยก็อย่าขโมยอีก แต่จงใช้มือทำงานที่ดีดีกว่า เพื่อจะได้มีอะไรๆแจกให้แก่คนที่ขัดสน"}], "ยากอบ 4:6-10": [{"n": "6", "t": "แต่พระองค์ก็ได้ทรงประทานพระคุณเพิ่มขึ้นอีก เหตุฉะนั้นพระคัมภีร์จึงกล่าวว่า พระเจ้าทรงต่อสู้ผู้ที่หยิ่งจองหอง แต่ทรงประทานพระคุณแก่คนที่ใจถ่อม"}, {"n": "7", "t": "เหตุฉะนั้นท่านทั้งหลายจงน้อมใจยอมฟังพระเจ้า จงต่อสู้กับมาร และมันจะหนีท่านไป"}, {"n": "8", "t": "ท่านทั้งหลายจงเข้าใกล้พระเจ้า และพระองค์จะเสด็จมาใกล้ท่าน คนบาปทั้งหลายเอ๋ย จงชำระมือให้สะอาด และคนสองใจ จงชำระใจของตนให้บริสุทธิ์"}, {"n": "9", "t": "จงเป็นทุกข์โศกเศร้าและร้องไห้ จงให้การหัวเราะกลับกลายเป็นการโศกเศร้า และความปีติยินดีกลับกลายเป็นความเศร้าสลด"}, {"n": "10", "t": "ท่านทั้งหลายจงถ่อมใจลงต่อองค์พระผู้เป็นเจ้า และพระองค์จะทรงยกชูท่านขึ้น"}], "กาลาเทีย 2:19-21": [{"n": "19", "t": "เหตุว่าโดยธรรมบัญญัตินั้น ข้าพเจ้าได้ตายจากธรรมบัญญัติแล้ว เพื่อจะได้มีชีวิตอยู่กับพระเจ้า"}, {"n": "20", "t": "ข้าพเจ้าถูกตรึงไว้กับพระคริสต์แล้ว ข้าพเจ้าเองไม่มีชีวิตอยู่ต่อไป แต่พระคริสต์ต่างหากที่ทรงมีชีวิตอยู่ในข้าพเจ้า ชีวิตซึ่งข้าพเจ้าดำเนินอยู่ในร่างกายขณะนี้ ข้าพเจ้าดำเนินอยู่โดยศรัทธาในพระบุตรของพระเจ้า ผู้ได้ทรงรักข้าพเจ้า และได้ทรงสละพระองค์เองเพื่อข้าพเจ้า"}, {"n": "21", "t": "ข้าพเจ้าไม่ได้กระทำให้พระคุณของพระเจ้าเป็นโมฆะ เพราะว่าถ้าความชอบธรรมเกิดจากธรรมบัญญัติแล้ว พระคริสต์ก็ทรงสิ้นพระชนม์โดยเปล่าประโยชน์"}], "ฮีบรู 13:7, 17-19": [{"n": "7", "t": "ท่านทั้งหลายจงระลึกถึงหัวหน้าของท่าน ผู้ซึ่งได้ประกาศพระวจนะของพระเจ้าแก่ท่าน และจงพิจารณาดูผลปลายทางที่เกิดแก่เขา แล้วจงตามอย่างความเชื่อของเขา"}, {"n": "17", "t": "ท่านทั้งหลายจงเชื่อฟังและยอมอยู่ในโอวาทของหัวหน้าของท่าน จงให้เขาทำงานนี้ด้วยความชื่นใจ ไม่ใช่ด้วยความเศร้าใจ ซึ่งจะไม่เป็นประโยชน์อะไรแก่ท่านทั้งหลายเลย เพราะว่าท่านเหล่านั้นดูแลรักษาจิตวิญญาณของท่านอยู่ เสมือนหนึ่งผู้ที่จะต้องเสนอรายงาน"}, {"n": "18", "t": "จงอธิษฐานเพื่อเรา เพราะเราแน่ใจว่า ใจของเราบริสุทธิ์อยู่แล้วและปรารถนาที่จะปฏิบัติสิ่งที่ดีงามทุกอย่าง"}, {"n": "19", "t": "ข้าพเจ้าขอเร่งเร้าท่านให้อธิษฐานเช่นนั้น เพื่อว่าข้าพเจ้าจะได้กลับคืนไปอยู่กับท่านเร็วยิ่งขึ้น"}], "1 เปโตร 5:1-7": [{"n": "1", "t": "เหตุฉะนั้นข้าพเจ้าจึงตักเตือนบรรดาผู้ใหญ่ในพวกท่านทั้งหลาย ในฐานะที่ข้าพเจ้าก็เป็นผู้ใหญ่คนหนึ่ง และเป็นพยานถึงความทุกข์ทรมานของพระคริสต์ และมีส่วนที่จะรับศักดิ์ศรีอันจะมาปรากฏภายหลัง"}, {"n": "2", "t": "จงเลี้ยงฝูงแกะของพระเจ้าที่อยู่ในความดูแลของท่าน {สำเนาต้นฉบับบางฉบับเพิ่มคำว่า เอาใจใส่ดูแล} ไม่ใช่ด้วยความฝืนใจแต่ด้วยความเต็มใจ {สำเนาต้นฉบับบางฉบับเพิ่มคำว่า ตามน้ำพระทัยของพระเจ้า} ไม่ใช่ด้วยการเห็นแก่ทรัพย์สิ่งของที่ได้มาโดยทุจริต แต่ด้วยใจเลื่อมใส"}, {"n": "3", "t": "และไม่ใช่เหมือนเป็นเจ้านายที่ข่มขี่ผู้ที่อยู่ใต้อำนาจ แต่เป็นแบบอย่างแก่ฝูงแกะนั้น"}, {"n": "4", "t": "และเมื่อพระผู้เลี้ยงผู้ยิ่งใหญ่จะเสด็จมาปรากฏ ท่านทั้งหลายจะรับศักดิ์ศรีเป็นมงกุฎที่ร่วงโรยไม่ได้เลย"}, {"n": "5", "t": "ในทำนองเดียวกันท่านที่อ่อนอาวุโส ก็จงเชื่อฟังคำของพวกผู้ใหญ่ อันที่จริงให้ท่านทุกคนมีความถ่อมใจในการปฏิบัติต่อกันและกัน ด้วยว่า พระเจ้าทรงเป็นปฏิปักษ์กับคนเหล่านั้นที่ถือตัวจองหอง แต่พระองค์ทรงสำแดงพระคุณแก่คนที่อ่อนน้อมถ่อมตน"}, {"n": "6", "t": "เหตุฉะนั้นท่านทั้งหลาย จงถ่อมใจลงภายใต้พระหัตถ์อันทรงฤทธิ์ของพระเจ้า เพื่อว่าพระองค์จะได้ทรงยกท่านขึ้นเมื่อถึงเวลาอันควร"}, {"n": "7", "t": "จงละความกระวนกระวายของท่านไว้กับพระองค์ เพราะว่าพระองค์ทรงห่วงใยท่านทั้งหลาย"}], "เอเฟซัส 4:11-16": [{"n": "11", "t": "ของประทานของพระองค์ ก็คือให้บางคนเป็นอัครทูต บางคนเป็นผู้เผยพระวจนะ บางคนเป็นผู้เผยแพร่ข่าวประเสริฐ บางคนเป็นศิษยาภิบาลและอาจารย์"}, {"n": "12", "t": "เพื่อเตรียมธรรมิกชนให้เป็นคนที่จะรับใช้ เพื่อเสริมสร้างพระกายของพระคริสต์ให้จำเริญขึ้น"}, {"n": "13", "t": "จนกว่าเราทุกคนจะบรรลุถึงความเป็นน้ำหนึ่งใจเดียวกันในความเชื่อ และในความรู้ถึงพระบุตรของพระเจ้า จนกว่าเราจะโตเป็นผู้ใหญ่เต็มที่ คือเต็มถึงขนาดความไพบูลย์ของพระคริสต์"}, {"n": "14", "t": "เพื่อเราจะไม่เป็นเด็กอีกต่อไป ถูกซัดไปซัดมาและหันไปเหมาด้วยลมปากแห่งคำสั่งสอนทุกอย่าง และด้วยเล่ห์กลของมนุษย์ตามอุบายฉลาดอันเป็นการล่อลวง"}, {"n": "15", "t": "แต่ให้เรายึดความจริงด้วยใจรัก เพื่อจะจำเริญขึ้นทุกอย่างสู่พระองค์ผู้เป็นศีรษะ คือพระคริสต์"}, {"n": "16", "t": "คือเนื่องจากพระองค์นั้น ร่างกายทั้งสิ้นที่ติดต่อสนิทและประสานกันโดยทุกๆข้อต่อ ที่ทรงประทานได้จำเริญเติบโตขึ้นด้วยความรัก เมื่ออวัยวะทุกอย่างทำงานตามความเหมาะสมแล้ว"}]};
const BIBLE_EN = {"กิจการฯ 2:42-47": [{"n": "42", "t": "And they continued stedfastly in the apostles' doctrine and fellowship, and in breaking of bread, and in prayers."}, {"n": "43", "t": "And fear came upon every soul: and many wonders and signs were done by the apostles."}, {"n": "44", "t": "And all that believed were together, and had all things common;"}, {"n": "45", "t": "And sold their possessions and goods, and parted them to all {men}, as every man had need."}, {"n": "46", "t": "And they, continuing daily with one accord in the temple, and breaking bread from house to house, did eat their meat with gladness and singleness of heart, {from...: or, at home}"}, {"n": "47", "t": "Praising God, and having favour with all the people. And the Lord added to the church daily such as should be saved."}], "กิจการฯ 4:32-35": [{"n": "32", "t": "And the multitude of them that believed were of one heart and of one soul: neither said any {of them} that ought of the things which he possessed was his own; but they had all things common."}, {"n": "33", "t": "And with great power gave the apostles witness of the resurrection of the Lord Jesus: and great grace was upon them all."}, {"n": "34", "t": "Neither was there any among them that lacked: for as many as were possessors of lands or houses sold them, and brought the prices of the things that were sold,"}, {"n": "35", "t": "And laid {them} down at the apostles' feet: and distribution was made unto every man according as he had need."}], "ฮีบรู 10:24-25": [{"n": "24", "t": "And let us consider one another to provoke unto love and to good works:"}, {"n": "25", "t": "Not forsaking the assembling of ourselves together, as the manner of some {is}; but exhorting {one another}: and so much the more, as ye see the day approaching."}], "โคโลสี 3:15-17": [{"n": "15", "t": "And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful."}, {"n": "16", "t": "Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord."}, {"n": "17", "t": "And whatsoever ye do in word or deed, {do} all in the name of the Lord Jesus, giving thanks to God and the Father by him."}], "สดุดี 95:1-7": [{"n": "1", "t": "O come, let us sing unto the LORD: let us make a joyful noise to the rock of our salvation."}, {"n": "2", "t": "Let us come before his presence with thanksgiving, and make a joyful noise unto him with psalms. {come...: Heb. prevent his face}"}, {"n": "3", "t": "For the LORD {is} a great God, and a great King above all gods."}, {"n": "4", "t": "In his hand {are} the deep places of the earth: the strength of the hills {is} his also. {In...: Heb. In whose} {the strength...: or, the heights of the hills are his}"}, {"n": "5", "t": "The sea {is} his, and he made it: and his hands formed the dry {land}. {The sea...: Heb. Whose the sea is}"}, {"n": "6", "t": "O come, let us worship and bow down: let us kneel before the LORD our maker."}, {"n": "7", "t": "For he {is} our God; and we {are} the people of his pasture, and the sheep of his hand. To day if ye will hear his voice,"}], "มัทธิว 6:5-15": [{"n": "5", "t": "And when thou prayest, thou shalt not be as the hypocrites {are}: for they love to pray standing in the synagogues and in the corners of the streets, that they may be seen of men. Verily I say unto you, They have their reward."}, {"n": "6", "t": "But thou, when thou prayest, enter into thy closet, and when thou hast shut thy door, pray to thy Father which is in secret; and thy Father which seeth in secret shall reward thee openly."}, {"n": "7", "t": "But when ye pray, use not vain repetitions, as the heathen {do}: for they think that they shall be heard for their much speaking."}, {"n": "8", "t": "Be not ye therefore like unto them: for your Father knoweth what things ye have need of, before ye ask him."}, {"n": "9", "t": "After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name."}, {"n": "10", "t": "Thy kingdom come. Thy will be done in earth, as {it is} in heaven."}, {"n": "11", "t": "Give us this day our daily bread."}, {"n": "12", "t": "And forgive us our debts, as we forgive our debtors."}, {"n": "13", "t": "And lead us not into temptation, but deliver us from evil: For thine is the kingdom, and the power, and the glory, for ever. Amen."}, {"n": "14", "t": "For if ye forgive men their trespasses, your heavenly Father will also forgive you:"}, {"n": "15", "t": "But if ye forgive not men their trespasses, neither will your Father forgive your trespasses."}], "ลูกา 6:16-18": [{"n": "16", "t": "And Judas {the brother} of James, and Judas Iscariot, which also was the traitor."}, {"n": "17", "t": "And he came down with them, and stood in the plain, and the company of his disciples, and a great multitude of people out of all Judaea and Jerusalem, and from the sea coast of Tyre and Sidon, which came to hear him, and to be healed of their diseases;"}, {"n": "18", "t": "And they that were vexed with unclean spirits: and they were healed."}], "ฟีลิปปี 4:6-7; 1 เปโตร 5:7": [{"n": "Philippians 4:6", "t": "Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God."}, {"n": "Philippians 4:7", "t": "And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus."}, {"n": "1 Peter 5:7", "t": "Casting all your care upon him; for he careth for you."}], "มัทธิว 4:1-11": [{"n": "1", "t": "Then was Jesus led up of the Spirit into the wilderness to be tempted of the devil."}, {"n": "2", "t": "And when he had fasted forty days and forty nights, he was afterward an hungred."}, {"n": "3", "t": "And when the tempter came to him, he said, If thou be the Son of God, command that these stones be made bread."}, {"n": "4", "t": "But he answered and said, It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God."}, {"n": "5", "t": "Then the devil taketh him up into the holy city, and setteth him on a pinnacle of the temple,"}, {"n": "6", "t": "And saith unto him, If thou be the Son of God, cast thyself down: for it is written, He shall give his angels charge concerning thee: and in {their} hands they shall bear thee up, lest at any time thou dash thy foot against a stone."}, {"n": "7", "t": "Jesus said unto him, It is written again, Thou shalt not tempt the Lord thy God. {tempt: or, try, or, put to trial, or, proof}"}, {"n": "8", "t": "Again, the devil taketh him up into an exceeding high mountain, and sheweth him all the kingdoms of the world, and the glory of them;"}, {"n": "9", "t": "And saith unto him, All these things will I give thee, if thou wilt fall down and worship me."}, {"n": "10", "t": "Then saith Jesus unto him, Get thee hence, Satan: for it is written, Thou shalt worship the Lord thy God, and him only shalt thou serve."}, {"n": "11", "t": "Then the devil leaveth him, and, behold, angels came and ministered unto him."}], "โยชูวา 24:15ข": [{"n": "15", "t": "And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that {were} on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD."}], "มัทธิว 6:19-21": [{"n": "19", "t": "Lay not up for yourselves treasures upon earth, where moth and rust doth corrupt, and where thieves break through and steal:"}, {"n": "20", "t": "But lay up for yourselves treasures in heaven, where neither moth nor rust doth corrupt, and where thieves do not break through nor steal:"}, {"n": "21", "t": "For where your treasure is, there will your heart be also."}], "มาระโก 12:41-44": [{"n": "41", "t": "And Jesus sat over against the treasury, and beheld how the people cast money into the treasury: and many that were rich cast in much. {money: a piece of brass money}"}, {"n": "42", "t": "And there came a certain poor widow, and she threw in two mites, which make a farthing. {mites: it is the seventh part of one piece of that brass money}"}, {"n": "43", "t": "And he called {unto him} his disciples, and saith unto them, Verily I say unto you, That this poor widow hath cast more in, than all they which have cast into the treasury:"}, {"n": "44", "t": "For all {they} did cast in of their abundance; but she of her want did cast in all that she had, {even} all her living."}], "กิจการฯ 9:36-39": [{"n": "36", "t": "Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did. {Dorcas: or, Doe, or, Roe}"}, {"n": "37", "t": "And it came to pass in those days, that she was sick, and died: whom when they had washed, they laid {her} in an upper chamber."}, {"n": "38", "t": "And forasmuch as Lydda was nigh to Joppa, and the disciples had heard that Peter was there, they sent unto him two men, desiring {him} that he would not delay to come to them. {delay: or, be grieved}"}, {"n": "39", "t": "Then Peter arose and went with them. When he was come, they brought him into the upper chamber: and all the widows stood by him weeping, and shewing the coats and garments which Dorcas made, while she was with them."}], "1 โครินธ์ 16:1-3": [{"n": "1", "t": "Now concerning the collection for the saints, as I have given order to the churches of Galatia, even so do ye."}, {"n": "2", "t": "Upon the first {day} of the week let every one of you lay by him in store, as {God} hath prospered him, that there be no gatherings when I come."}, {"n": "3", "t": "And when I come, whomsoever ye shall approve by {your} letters, them will I send to bring your liberality unto Jerusalem. {liberality: Gr. gift}"}], "1 เปโตร 4:10-11": [{"n": "10", "t": "As every man hath received the gift, {even so} minister the same one to another, as good stewards of the manifold grace of God."}, {"n": "11", "t": "If any man speak, {let him speak} as the oracles of God; if any man minister, {let him do it} as of the ability which God giveth: that God in all things may be glorified through Jesus Christ, to whom be praise and dominion for ever and ever. Amen."}], "ยอห์น 15:4-10": [{"n": "4", "t": "Abide in me, and I in you. As the branch cannot bear fruit of itself, except it abide in the vine; no more can ye, except ye abide in me."}, {"n": "5", "t": "I am the vine, ye {are} the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing. {without me: or, severed from me}"}, {"n": "6", "t": "If a man abide not in me, he is cast forth as a branch, and is withered; and men gather them, and cast {them} into the fire, and they are burned."}, {"n": "7", "t": "If ye abide in me, and my words abide in you, ye shall ask what ye will, and it shall be done unto you."}, {"n": "8", "t": "Herein is my Father glorified, that ye bear much fruit; so shall ye be my disciples."}, {"n": "9", "t": "As the Father hath loved me, so have I loved you: continue ye in my love."}, {"n": "10", "t": "If ye keep my commandments, ye shall abide in my love; even as I have kept my Father's commandments, and abide in his love."}], "กาลาเทีย 5:16-26": [{"n": "16", "t": "{This} I say then, Walk in the Spirit, and ye shall not fulfil the lust of the flesh. {ye...: or, fulfil not}"}, {"n": "17", "t": "For the flesh lusteth against the Spirit, and the Spirit against the flesh: and these are contrary the one to the other: so that ye cannot do the things that ye would."}, {"n": "18", "t": "But if ye be led of the Spirit, ye are not under the law."}, {"n": "19", "t": "Now the works of the flesh are manifest, which are {these}; Adultery, fornication, uncleanness, lasciviousness,"}, {"n": "20", "t": "Idolatry, witchcraft, hatred, variance, emulations, wrath, strife, seditions, heresies,"}, {"n": "21", "t": "Envyings, murders, drunkenness, revellings, and such like: of the which I tell you before, as I have also told {you} in time past, that they which do such things shall not inherit the kingdom of God."}, {"n": "22", "t": "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,"}, {"n": "23", "t": "Meekness, temperance: against such there is no law."}, {"n": "24", "t": "And they that are Christ's have crucified the flesh with the affections and lusts. {affections: or, passions}"}, {"n": "25", "t": "If we live in the Spirit, let us also walk in the Spirit."}, {"n": "26", "t": "Let us not be desirous of vain glory, provoking one another, envying one another."}], "1 เปโตร 1:3-9": [{"n": "3", "t": "Blessed {be} the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead, {abundant: Gr. much}"}, {"n": "4", "t": "To an inheritance incorruptible, and undefiled, and that fadeth not away, reserved in heaven for you, {for you: or, for us}"}, {"n": "5", "t": "Who are kept by the power of God through faith unto salvation ready to be revealed in the last time."}, {"n": "6", "t": "Wherein ye greatly rejoice, though now for a season, if need be, ye are in heaviness through manifold temptations:"}, {"n": "7", "t": "That the trial of your faith, being much more precious than of gold that perisheth, though it be tried with fire, might be found unto praise and honour and glory at the appearing of Jesus Christ:"}, {"n": "8", "t": "Whom having not seen, ye love; in whom, though now ye see {him} not, yet believing, ye rejoice with joy unspeakable and full of glory:"}, {"n": "9", "t": "Receiving the end of your faith, {even} the salvation of {your} souls."}], "โรม 8:1-11": [{"n": "1", "t": "{There is} therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit."}, {"n": "2", "t": "For the law of the Spirit of life in Christ Jesus hath made me free from the law of sin and death."}, {"n": "3", "t": "For what the law could not do, in that it was weak through the flesh, God sending his own Son in the likeness of sinful flesh, and for sin, condemned sin in the flesh: {for sin: or, by a sacrifice for sin}"}, {"n": "4", "t": "That the righteousness of the law might be fulfilled in us, who walk not after the flesh, but after the Spirit."}, {"n": "5", "t": "For they that are after the flesh do mind the things of the flesh; but they that are after the Spirit the things of the Spirit."}, {"n": "6", "t": "For to be carnally minded {is} death; but to be spiritually minded {is} life and peace. {to be carnally...: Gr. the minding of the flesh} {to be spiritually...: Gr. the minding of the Spirit}"}, {"n": "7", "t": "Because the carnal mind {is} enmity against God: for it is not subject to the law of God, neither indeed can be. {the carnal...: Gr. the minding of the flesh}"}, {"n": "8", "t": "So then they that are in the flesh cannot please God."}, {"n": "9", "t": "But ye are not in the flesh, but in the Spirit, if so be that the Spirit of God dwell in you. Now if any man have not the Spirit of Christ, he is none of his."}, {"n": "10", "t": "And if Christ {be} in you, the body {is} dead because of sin; but the Spirit {is} life because of righteousness."}, {"n": "11", "t": "But if the Spirit of him that raised up Jesus from the dead dwell in you, he that raised up Christ from the dead shall also quicken your mortal bodies by his Spirit that dwelleth in you. {by: or, because of}"}], "โรม 8:31-37": [{"n": "31", "t": "What shall we then say to these things? If God {be} for us, who {can be} against us?"}, {"n": "32", "t": "He that spared not his own Son, but delivered him up for us all, how shall he not with him also freely give us all things?"}, {"n": "33", "t": "Who shall lay any thing to the charge of God's elect? {It is} God that justifieth."}, {"n": "34", "t": "Who {is} he that condemneth? {It is} Christ that died, yea rather, that is risen again, who is even at the right hand of God, who also maketh intercession for us."}, {"n": "35", "t": "Who shall separate us from the love of Christ? {shall} tribulation, or distress, or persecution, or famine, or nakedness, or peril, or sword?"}, {"n": "36", "t": "As it is written, For thy sake we are killed all the day long; we are accounted as sheep for the slaughter."}, {"n": "37", "t": "Nay, in all these things we are more than conquerors through him that loved us."}], "ยอห์น 14:15-21": [{"n": "15", "t": "If ye love me, keep my commandments."}, {"n": "16", "t": "And I will pray the Father, and he shall give you another Comforter, that he may abide with you for ever;"}, {"n": "17", "t": "{Even} the Spirit of truth; whom the world cannot receive, because it seeth him not, neither knoweth him: but ye know him; for he dwelleth with you, and shall be in you."}, {"n": "18", "t": "I will not leave you comfortless: I will come to you. {comfortless: or, orphans}"}, {"n": "19", "t": "Yet a little while, and the world seeth me no more; but ye see me: because I live, ye shall live also."}, {"n": "20", "t": "At that day ye shall know that I {am} in my Father, and ye in me, and I in you."}, {"n": "21", "t": "He that hath my commandments, and keepeth them, he it is that loveth me: and he that loveth me shall be loved of my Father, and I will love him, and will manifest myself to him."}], "มัทธิว 25:35-36": [{"n": "35", "t": "For I was an hungred, and ye gave me meat: I was thirsty, and ye gave me drink: I was a stranger, and ye took me in:"}, {"n": "36", "t": "Naked, and ye clothed me: I was sick, and ye visited me: I was in prison, and ye came unto me."}], "1 โครินธ์ 13:4-7": [{"n": "4", "t": "Charity suffereth long, {and} is kind; charity envieth not; charity vaunteth not itself, is not puffed up, {vaunteth...: or, is not rash}"}, {"n": "5", "t": "Doth not behave itself unseemly, seeketh not her own, is not easily provoked, thinketh no evil;"}, {"n": "6", "t": "Rejoiceth not in iniquity, but rejoiceth in the truth; {in the truth: or, with the truth}"}, {"n": "7", "t": "Beareth all things, believeth all things, hopeth all things, endureth all things."}], "ลูกา 10:25-37": [{"n": "25", "t": "And, behold, a certain lawyer stood up, and tempted him, saying, Master, what shall I do to inherit eternal life?"}, {"n": "26", "t": "He said unto him, What is written in the law? how readest thou?"}, {"n": "27", "t": "And he answering said, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy strength, and with all thy mind; and thy neighbour as thyself."}, {"n": "28", "t": "And he said unto him, Thou hast answered right: this do, and thou shalt live."}, {"n": "29", "t": "But he, willing to justify himself, said unto Jesus, And who is my neighbour?"}, {"n": "30", "t": "And Jesus answering said, A certain {man} went down from Jerusalem to Jericho, and fell among thieves, which stripped him of his raiment, and wounded {him}, and departed, leaving {him} half dead."}, {"n": "31", "t": "And by chance there came down a certain priest that way: and when he saw him, he passed by on the other side."}, {"n": "32", "t": "And likewise a Levite, when he was at the place, came and looked {on him}, and passed by on the other side."}, {"n": "33", "t": "But a certain Samaritan, as he journeyed, came where he was: and when he saw him, he had compassion {on him},"}, {"n": "34", "t": "And went to {him}, and bound up his wounds, pouring in oil and wine, and set him on his own beast, and brought him to an inn, and took care of him."}, {"n": "35", "t": "And on the morrow when he departed, he took out two pence, and gave {them} to the host, and said unto him, Take care of him; and whatsoever thou spendest more, when I come again, I will repay thee."}, {"n": "36", "t": "Which now of these three, thinkest thou, was neighbour unto him that fell among the thieves?"}, {"n": "37", "t": "And he said, He that shewed mercy on him. Then said Jesus unto him, Go, and do thou likewise."}], "มัทธิว 5:43-48": [{"n": "43", "t": "Ye have heard that it hath been said, Thou shalt love thy neighbour, and hate thine enemy."}, {"n": "44", "t": "But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you;"}, {"n": "45", "t": "That ye may be the children of your Father which is in heaven: for he maketh his sun to rise on the evil and on the good, and sendeth rain on the just and on the unjust."}, {"n": "46", "t": "For if ye love them which love you, what reward have ye? do not even the publicans the same?"}, {"n": "47", "t": "And if ye salute your brethren only, what do ye more {than others}? do not even the publicans so?"}, {"n": "48", "t": "Be ye therefore perfect, even as your Father which is in heaven is perfect."}], "มัทธิว 26:26-30": [{"n": "26", "t": "And as they were eating, Jesus took bread, and blessed {it}, and brake {it}, and gave {it} to the disciples, and said, Take, eat; this is my body. {blessed it: many Greek copies have gave thanks}"}, {"n": "27", "t": "And he took the cup, and gave thanks, and gave {it} to them, saying, Drink ye all of it;"}, {"n": "28", "t": "For this is my blood of the new testament, which is shed for many for the remission of sins."}, {"n": "29", "t": "But I say unto you, I will not drink henceforth of this fruit of the vine, until that day when I drink it new with you in my Father's kingdom."}, {"n": "30", "t": "And when they had sung an hymn, they went out into the mount of Olives. {hymn: or, psalm}"}], "1 โครินธ์ 11:23-29": [{"n": "23", "t": "For I have received of the Lord that which also I delivered unto you, That the Lord Jesus the {same} night in which he was betrayed took bread:"}, {"n": "24", "t": "And when he had given thanks, he brake {it}, and said, Take, eat: this is my body, which is broken for you: this do in remembrance of me. {in...: or, for a remembrance}"}, {"n": "25", "t": "After the same manner also {he took} the cup, when he had supped, saying, This cup is the new testament in my blood: this do ye, as oft as ye drink {it}, in remembrance of me."}, {"n": "26", "t": "For as often as ye eat this bread, and drink this cup, ye do shew the Lord's death till he come. {ye do...: or, shew ye}"}, {"n": "27", "t": "Wherefore whosoever shall eat this bread, and drink {this} cup of the Lord, unworthily, shall be guilty of the body and blood of the Lord."}, {"n": "28", "t": "But let a man examine himself, and so let him eat of {that} bread, and drink of {that} cup."}, {"n": "29", "t": "For he that eateth and drinketh unworthily, eateth and drinketh damnation to himself, not discerning the Lord's body. {damnation: or, judgment}"}], "มัทธิว 28:19-20": [{"n": "19", "t": "Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost: {teach...: or, make disciples, or, Christians of all nations}"}, {"n": "20", "t": "Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, {even} unto the end of the world. Amen."}], "กิจการฯ 8:26-39": [{"n": "26", "t": "And the angel of the Lord spake unto Philip, saying, Arise, and go toward the south unto the way that goeth down from Jerusalem unto Gaza, which is desert."}, {"n": "27", "t": "And he arose and went: and, behold, a man of Ethiopia, an eunuch of great authority under Candace queen of the Ethiopians, who had the charge of all her treasure, and had come to Jerusalem for to worship,"}, {"n": "28", "t": "Was returning, and sitting in his chariot read Esaias the prophet."}, {"n": "29", "t": "Then the Spirit said unto Philip, Go near, and join thyself to this chariot."}, {"n": "30", "t": "And Philip ran thither to {him}, and heard him read the prophet Esaias, and said, Understandest thou what thou readest?"}, {"n": "31", "t": "And he said, How can I, except some man should guide me? And he desired Philip that he would come up and sit with him."}, {"n": "32", "t": "The place of the scripture which he read was this, He was led as a sheep to the slaughter; and like a lamb dumb before his shearer, so opened he not his mouth:"}, {"n": "33", "t": "In his humiliation his judgment was taken away: and who shall declare his generation? for his life is taken from the earth."}, {"n": "34", "t": "And the eunuch answered Philip, and said, I pray thee, of whom speaketh the prophet this? of himself, or of some other man?"}, {"n": "35", "t": "Then Philip opened his mouth, and began at the same scripture, and preached unto him Jesus."}, {"n": "36", "t": "And as they went on {their} way, they came unto a certain water: and the eunuch said, See, {here is} water; what doth hinder me to be baptized?"}, {"n": "37", "t": "And Philip said, If thou believest with all thine heart, thou mayest. And he answered and said, I believe that Jesus Christ is the Son of God."}, {"n": "38", "t": "And he commanded the chariot to stand still: and they went down both into the water, both Philip and the eunuch; and he baptized him."}, {"n": "39", "t": "And when they were come up out of the water, the Spirit of the Lord caught away Philip, that the eunuch saw him no more: and he went on his way rejoicing."}], "โรม 6:1-9": [{"n": "1", "t": "What shall we say then? Shall we continue in sin, that grace may abound?"}, {"n": "2", "t": "God forbid. How shall we, that are dead to sin, live any longer therein?"}, {"n": "3", "t": "Know ye not, that so many of us as were baptized into Jesus Christ were baptized into his death? {were: or, are}"}, {"n": "4", "t": "Therefore we are buried with him by baptism into death: that like as Christ was raised up from the dead by the glory of the Father, even so we also should walk in newness of life."}, {"n": "5", "t": "For if we have been planted together in the likeness of his death, we shall be also {in the likeness} of {his} resurrection:"}, {"n": "6", "t": "Knowing this, that our old man is crucified with {him}, that the body of sin might be destroyed, that henceforth we should not serve sin."}, {"n": "7", "t": "For he that is dead is freed from sin. {freed: Gr. justified}"}, {"n": "8", "t": "Now if we be dead with Christ, we believe that we shall also live with him:"}, {"n": "9", "t": "Knowing that Christ being raised from the dead dieth no more; death hath no more dominion over him."}], "2 ทิโมธี 3:10-17": [{"n": "10", "t": "But thou hast fully known my doctrine, manner of life, purpose, faith, longsuffering, charity, patience, {fully...: or, been a diligent follower of}"}, {"n": "11", "t": "Persecutions, afflictions, which came unto me at Antioch, at Iconium, at Lystra; what persecutions I endured: but out of {them} all the Lord delivered me."}, {"n": "12", "t": "Yea, and all that will live godly in Christ Jesus shall suffer persecution."}, {"n": "13", "t": "But evil men and seducers shall wax worse and worse, deceiving, and being deceived."}, {"n": "14", "t": "But continue thou in the things which thou hast learned and hast been assured of, knowing of whom thou hast learned {them};"}, {"n": "15", "t": "And that from a child thou hast known the holy scriptures, which are able to make thee wise unto salvation through faith which is in Christ Jesus."}, {"n": "16", "t": "All scripture {is} given by inspiration of God, and {is} profitable for doctrine, for reproof, for correction, for instruction in righteousness:"}, {"n": "17", "t": "That the man of God may be perfect, throughly furnished unto all good works. {throughly...: or, perfected}"}], "โยชูวา 1:7-9": [{"n": "7", "t": "Only be thou strong and very courageous, that thou mayest observe to do according to all the law, which Moses my servant commanded thee: turn not from it {to} the right hand or {to} the left, that thou mayest prosper whithersoever thou goest. {prosper: or, do wisely}"}, {"n": "8", "t": "This book of the law shall not depart out of thy mouth; but thou shalt meditate therein day and night, that thou mayest observe to do according to all that is written therein: for then thou shalt make thy way prosperous, and then thou shalt have good success. {have...: or, do wisely}"}, {"n": "9", "t": "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God {is} with thee whithersoever thou goest."}], "ยากอบ 1:22-25": [{"n": "22", "t": "But be ye doers of the word, and not hearers only, deceiving your own selves."}, {"n": "23", "t": "For if any be a hearer of the word, and not a doer, he is like unto a man beholding his natural face in a glass:"}, {"n": "24", "t": "For he beholdeth himself, and goeth his way, and straightway forgetteth what manner of man he was."}, {"n": "25", "t": "But whoso looketh into the perfect law of liberty, and continueth {therein}, he being not a forgetful hearer, but a doer of the work, this man shall be blessed in his deed. {deed: or, doing}"}], "ฉธบ. 31:12-13": [{"n": "12", "t": "Gather the people together, men, and women, and children, and thy stranger that {is} within thy gates, that they may hear, and that they may learn, and fear the LORD your God, and observe to do all the words of this law:"}, {"n": "13", "t": "And {that} their children, which have not known {any thing}, may hear, and learn to fear the LORD your God, as long as ye live in the land whither ye go over Jordan to possess it."}], "กิจการฯ 17:11": [{"n": "11", "t": "These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so."}], "มัทธิว 28:18-20": [{"n": "18", "t": "And Jesus came and spake unto them, saying, All power is given unto me in heaven and in earth."}, {"n": "19", "t": "Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost: {teach...: or, make disciples, or, Christians of all nations}"}, {"n": "20", "t": "Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, {even} unto the end of the world. Amen."}], "2 ทิโมธี 2:1-3": [{"n": "1", "t": "Thou therefore, my son, be strong in the grace that is in Christ Jesus."}, {"n": "2", "t": "And the things that thou hast heard of me among many witnesses, the same commit thou to faithful men, who shall be able to teach others also. {among: or, by}"}, {"n": "3", "t": "Thou therefore endure hardness, as a good soldier of Jesus Christ."}], "กิจการฯ 18:24-27": [{"n": "24", "t": "And a certain Jew named Apollos, born at Alexandria, an eloquent man, {and} mighty in the scriptures, came to Ephesus."}, {"n": "25", "t": "This man was instructed in the way of the Lord; and being fervent in the spirit, he spake and taught diligently the things of the Lord, knowing only the baptism of John."}, {"n": "26", "t": "And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto {them}, and expounded unto him the way of God more perfectly."}, {"n": "27", "t": "And when he was disposed to pass into Achaia, the brethren wrote, exhorting the disciples to receive him: who, when he was come, helped them much which had believed through grace:"}], "ลูกา 10:1-9": [{"n": "1", "t": "After these things the Lord appointed other seventy also, and sent them two and two before his face into every city and place, whither he himself would come."}, {"n": "2", "t": "Therefore said he unto them, The harvest truly {is} great, but the labourers {are} few: pray ye therefore the Lord of the harvest, that he would send forth labourers into his harvest."}, {"n": "3", "t": "Go your ways: behold, I send you forth as lambs among wolves."}, {"n": "4", "t": "Carry neither purse, nor scrip, nor shoes: and salute no man by the way."}, {"n": "5", "t": "And into whatsoever house ye enter, first say, Peace {be} to this house."}, {"n": "6", "t": "And if the son of peace be there, your peace shall rest upon it: if not, it shall turn to you again."}, {"n": "7", "t": "And in the same house remain, eating and drinking such things as they give: for the labourer is worthy of his hire. Go not from house to house."}, {"n": "8", "t": "And into whatsoever city ye enter, and they receive you, eat such things as are set before you:"}, {"n": "9", "t": "And heal the sick that are therein, and say unto them, The kingdom of God is come nigh unto you."}], "เอเฟซัส 4:17-28": [{"n": "17", "t": "This I say therefore, and testify in the Lord, that ye henceforth walk not as other Gentiles walk, in the vanity of their mind,"}, {"n": "18", "t": "Having the understanding darkened, being alienated from the life of God through the ignorance that is in them, because of the blindness of their heart: {blindness: or, hardness}"}, {"n": "19", "t": "Who being past feeling have given themselves over unto lasciviousness, to work all uncleanness with greediness."}, {"n": "20", "t": "But ye have not so learned Christ;"}, {"n": "21", "t": "If so be that ye have heard him, and have been taught by him, as the truth is in Jesus:"}, {"n": "22", "t": "That ye put off concerning the former conversation the old man, which is corrupt according to the deceitful lusts;"}, {"n": "23", "t": "And be renewed in the spirit of your mind;"}, {"n": "24", "t": "And that ye put on the new man, which after God is created in righteousness and true holiness. {true...: or, holiness of truth}"}, {"n": "25", "t": "Wherefore putting away lying, speak every man truth with his neighbour: for we are members one of another."}, {"n": "26", "t": "Be ye angry, and sin not: let not the sun go down upon your wrath:"}, {"n": "27", "t": "Neither give place to the devil."}, {"n": "28", "t": "Let him that stole steal no more: but rather let him labour, working with {his} hands the thing which is good, that he may have to give to him that needeth. {to give: or, to distribute}"}], "ยากอบ 4:6-10": [{"n": "6", "t": "But he giveth more grace. Wherefore he saith, God resisteth the proud, but giveth grace unto the humble."}, {"n": "7", "t": "Submit yourselves therefore to God. Resist the devil, and he will flee from you."}, {"n": "8", "t": "Draw nigh to God, and he will draw nigh to you. Cleanse {your} hands, {ye} sinners; and purify {your} hearts, {ye} double minded."}, {"n": "9", "t": "Be afflicted, and mourn, and weep: let your laughter be turned to mourning, and {your} joy to heaviness."}, {"n": "10", "t": "Humble yourselves in the sight of the Lord, and he shall lift you up."}], "กาลาเทีย 2:19-21": [{"n": "19", "t": "For I through the law am dead to the law, that I might live unto God."}, {"n": "20", "t": "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me."}, {"n": "21", "t": "I do not frustrate the grace of God: for if righteousness {come} by the law, then Christ is dead in vain."}], "ฮีบรู 13:7, 17-19": [{"n": "7", "t": "Remember them which have the rule over you, who have spoken unto you the word of God: whose faith follow, considering the end of {their} conversation. {have the rule: or, are the guides}"}, {"n": "17", "t": "Obey them that have the rule over you, and submit yourselves: for they watch for your souls, as they that must give account, that they may do it with joy, and not with grief: for that {is} unprofitable for you. {have...: or, guide}"}, {"n": "18", "t": "Pray for us: for we trust we have a good conscience, in all things willing to live honestly."}, {"n": "19", "t": "But I beseech {you} the rather to do this, that I may be restored to you the sooner."}], "1 เปโตร 5:1-7": [{"n": "1", "t": "The elders which are among you I exhort, who am also an elder, and a witness of the sufferings of Christ, and also a partaker of the glory that shall be revealed:"}, {"n": "2", "t": "Feed the flock of God which is among you, taking the oversight {thereof}, not by constraint, but willingly; not for filthy lucre, but of a ready mind; {which...: or, as much as in you is}"}, {"n": "3", "t": "Neither as being lords over {God's} heritage, but being ensamples to the flock. {being lords over: or, overruling}"}, {"n": "4", "t": "And when the chief Shepherd shall appear, ye shall receive a crown of glory that fadeth not away."}, {"n": "5", "t": "Likewise, ye younger, submit yourselves unto the elder. Yea, all {of you} be subject one to another, and be clothed with humility: for God resisteth the proud, and giveth grace to the humble."}, {"n": "6", "t": "Humble yourselves therefore under the mighty hand of God, that he may exalt you in due time:"}, {"n": "7", "t": "Casting all your care upon him; for he careth for you."}], "เอเฟซัส 4:11-16": [{"n": "11", "t": "And he gave some, apostles; and some, prophets; and some, evangelists; and some, pastors and teachers;"}, {"n": "12", "t": "For the perfecting of the saints, for the work of the ministry, for the edifying of the body of Christ:"}, {"n": "13", "t": "Till we all come in the unity of the faith, and of the knowledge of the Son of God, unto a perfect man, unto the measure of the stature of the fulness of Christ: {in: or, into} {stature: or, age}"}, {"n": "14", "t": "That we {henceforth} be no more children, tossed to and fro, and carried about with every wind of doctrine, by the sleight of men, {and} cunning craftiness, whereby they lie in wait to deceive;"}, {"n": "15", "t": "But speaking the truth in love, may grow up into him in all things, which is the head, {even} Christ: {speaking...: or, being sincere}"}, {"n": "16", "t": "From whom the whole body fitly joined together and compacted by that which every joint supplieth, according to the effectual working in the measure of every part, maketh increase of the body unto the edifying of itself in love."}]};
